-- Source211 UNWIRED native slice; not a migration registration or installed profile.
-- Parent148 proof is financial provenance, never a PZ, receipt169 or new stock effect.
-- The separately reviewed forward installer must add exact catalogue projections,
-- old206 FK replacement, historical206 parent seeding and source/frame/issue wiring.
-- This file only defines new211 objects; old148/169/188/206/209/210 bytes stay literal.
DO $pre211$ BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('session_replication_role')<>'origin'
 OR public.order_merge_delivery209_valid() IS DISTINCT FROM true
 OR EXISTS(SELECT FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'order_split210_'))
 OR EXISTS(SELECT FROM pg_class WHERE relnamespace='public'::regnamespace AND starts_with(relname,'order_split210_')) THEN
  RAISE EXCEPTION '211 exact active209 without210 required' USING ERRCODE='55000';END IF;
END $pre211$;

CREATE FUNCTION public.return_credit211_frozen_physical(eid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;a public.return_destination_admissions;cur jsonb;nm text;old_rows jsonb;new_rows jsonb;expected jsonb;actual jsonb;wr jsonb;live jsonb;cell jsonb;rec record;want_qty bigint;want_updates bigint;before_row jsonb;after_row jsonb;op public.wms_operations;expected_request jsonb;rc public.return_cases;all_accepted boolean;BEGIN
 IF session_user<>'postgres' OR current_user<>'postgres' OR t IS NULL OR current_setting('session_replication_role')<>'origin' THEN RAISE EXCEPTION '211 owner tenant origin required' USING ERRCODE='42501';END IF;
 SELECT * INTO a FROM public.return_destination_admissions WHERE(tenant_id,receipt_id)=(t,eid);
 IF a.receipt_id IS NULL OR a.before_snapshot='{}' OR a.after_snapshot IS NULL OR a.transaction_id=pg_current_xact_id() OR a.payload->>'action' IS DISTINCT FROM 'receive' OR a.payload#>>'{snapshot,protocol}' IS DISTINCT FROM 'destinations_v1' THEN RAISE EXCEPTION '211 completed historical receive148 required' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.wms_issue_fragments f WHERE(f.tenant_id,f.operation_id)=(t,eid)) THEN RAISE EXCEPTION 'Przyjęcie do celów nie może tworzyć fragmentu wydania' USING ERRCODE='23514';END IF;
 cur:=a.after_snapshot;
 SELECT expanded.* INTO rc FROM jsonb_array_elements(cur->'return_cases')entry CROSS JOIN LATERAL jsonb_populate_record(NULL::public.return_cases,entry)expanded WHERE entry->>'id'=a.return_id::text;
 IF rc.id IS NULL OR rc.version IS DISTINCT FROM(a.payload->'receive_input'->>'version')::bigint+1 OR rc.decision_note IS DISTINCT FROM a.payload->'receive_input'->>'note' THEN RAISE EXCEPTION 'Przyjęcie nie ma rzeczywistego wyniku core' USING ERRCODE='23514';END IF;
 IF a.payload->>'action'='receive' THEN
  IF rc.state IS DISTINCT FROM 'refund_pending' OR rc.receipt IS DISTINCT FROM a.payload->'receive_input' OR rc.received_at IS NULL OR rc.received_at>(SELECT received_birth.created_at FROM public.return_assistant_receipts received_birth WHERE(received_birth.tenant_id,received_birth.id)=(t,eid)) OR rc.refund_amount IS DISTINCT FROM(a.payload->'plan'->'summary'->>'commercial_credit_minor')::bigint OR rc.refunded_shipping IS DISTINCT FROM(a.payload->'plan'->'summary'->>'shipping_refund_minor')::bigint OR rc.receipt_sequence IS DISTINCT FROM(a.payload->'snapshot'->'source'->>'next_receipt_sequence')::int THEN RAISE EXCEPTION 'Core ma inne ilości lub finansowy wynik przyjęcia' USING ERRCODE='23514';END IF;
 ELSE IF rc.state IS DISTINCT FROM 'rejected' OR rc.receipt IS NOT NULL OR rc.received_at IS NOT NULL OR rc.refund_amount<>0 OR rc.refunded_shipping<>0 THEN RAISE EXCEPTION 'Odrzucenie nie może przyjmować ani zwracać pieniędzy' USING ERRCODE='23514';END IF;END IF;
 FOR rec IN SELECT b,c FROM jsonb_array_elements(a.before_snapshot->'return_cases')b FULL JOIN jsonb_array_elements(cur->'return_cases')c ON b->>'id'=c->>'id' LOOP
  IF rec.b IS NULL OR rec.c IS NULL OR(rec.b->>'id'<>a.return_id::text AND rec.b IS DISTINCT FROM rec.c) OR(rec.b->>'id'=a.return_id::text AND rec.b-ARRAY['state','received_at','receipt','receipt_sequence','refunded_shipping','refund_amount','decision_note','version','updated_at'] IS DISTINCT FROM rec.c-ARRAY['state','received_at','receipt','receipt_sequence','refunded_shipping','refund_amount','decision_note','version','updated_at']) THEN RAISE EXCEPTION 'Przyjęcie zmieniło niezatwierdzony nagłówek RMA' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR rec IN SELECT b,c FROM jsonb_array_elements(a.before_snapshot->'return_items')b FULL JOIN jsonb_array_elements(cur->'return_items')c ON(b->>'return_id',b->>'item_id')=(c->>'return_id',c->>'item_id') LOOP
  IF rec.b IS NULL OR rec.c IS NULL OR(rec.b->>'return_id'<>a.return_id::text AND rec.b IS DISTINCT FROM rec.c) OR(rec.b->>'return_id'=a.return_id::text AND rec.b-ARRAY['accepted','restocked','refund_amount'] IS DISTINCT FROM rec.c-ARRAY['accepted','restocked','refund_amount']) THEN RAISE EXCEPTION 'Historyczna pozycja lub receptura RMA zmieniła się' USING ERRCODE='23514';END IF;
  IF rec.b->>'return_id'=a.return_id::text THEN
   SELECT x INTO expected FROM jsonb_array_elements(a.payload->'plan'->'decisions')x WHERE x->>'item_id'=rec.b->>'item_id';
   IF expected IS NULL OR(rec.c->>'accepted',rec.c->>'restocked',rec.c->>'refund_amount') IS DISTINCT FROM(expected->>'accepted',expected->>'restocked',expected->>'refund_minor') THEN RAISE EXCEPTION 'Ilości lub skumulowany kredyt nie odpowiadają pozycji' USING ERRCODE='23514';END IF;
  END IF;
 END LOOP;
 SELECT bool_and((oi->>'quantity')::bigint=(SELECT coalesce(sum((ri->>'accepted')::bigint),0) FROM jsonb_array_elements(cur->'return_items')ri JOIN jsonb_array_elements(cur->'return_cases')rr ON rr->>'id'=ri->>'return_id' WHERE ri->>'order_id'=a.order_id::text AND ri->>'item_id'=oi->>'id' AND rr->>'state' IN('refund_pending','closed'))) INTO all_accepted FROM jsonb_array_elements(cur->'order_items')oi;
 before_row:=a.before_snapshot->'orders'->0;after_row:=cur->'orders'->0;
 IF before_row IS NULL OR after_row IS NULL OR before_row-ARRAY['status','workflow_status_id','version','updated_at'] IS DISTINCT FROM after_row-ARRAY['status','workflow_status_id','version','updated_at']
 OR after_row->>'status' IS DISTINCT FROM(CASE WHEN a.payload->>'action'='receive' AND all_accepted THEN 'return_received' ELSE before_row->>'status' END)
 OR after_row->'workflow_status_id' IS DISTINCT FROM(CASE WHEN a.payload->>'action'='receive' AND all_accepted THEN 'null'::jsonb ELSE before_row->'workflow_status_id' END)
 OR(after_row->>'version')::bigint IS DISTINCT FROM(before_row->>'version')::bigint+(CASE WHEN a.payload->>'action'='receive' AND all_accepted THEN 2 ELSE 1 END) THEN RAISE EXCEPTION 'Przyjęcie zmieniło niezatwierdzone dane zamówienia' USING ERRCODE='23514';END IF;
 -- Current policy/status/catalogue state is not replayed. history148 authenticates
 -- the immutable revision and recomputes the original plan before this call.
 -- Exact prior rows survive, then every new journal row is a genuine witness.
 FOREACH nm IN ARRAY ARRAY['stock_movements','stock_location_movements','wms_layer_movements','wms_return_fragments','wms_operations'] LOOP
  old_rows:=a.before_snapshot->nm;new_rows:=cur->nm;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(old_rows)x WHERE NOT(new_rows @> jsonb_build_array(x))) THEN RAISE EXCEPTION 'Przyjęcie zmieniło wcześniejszy dziennik' USING ERRCODE='23514';END IF;
  SELECT coalesce(jsonb_agg(x ORDER BY x->>'id'),'[]') INTO actual FROM jsonb_array_elements(new_rows)x WHERE NOT(old_rows @> jsonb_build_array(x));
  SELECT coalesce(jsonb_agg(w->'row' ORDER BY w->'row'->>'id'),'[]') INTO expected FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'=nm;
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Przyjęcie wymaga bijekcji rzeczywistych dzienników' USING ERRCODE='23514';END IF;
 END LOOP;
 FOREACH nm IN ARRAY ARRAY['order_items','payment_entries','documents','reservations','reservation_locations','wms_reservation_layers','shipments','order_parcel_dispatches','order_parcel_releases','wms_cost_layers','wms_lots','wms_issue_fragments'] LOOP
  IF cur->nm IS DISTINCT FROM a.before_snapshot->nm THEN RAISE EXCEPTION 'Przyjęcie zmieniło wydanie, kasę, dokument lub oryginalny koszt' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR wr IN SELECT value FROM jsonb_array_elements(a.witnesses) LOOP
  IF wr->>'table' NOT IN('stock_movements','stock_location_movements','wms_return_fragments','wms_layer_movements','wms_operations') THEN RAISE EXCEPTION 'Obcy typ świadka przyjęcia' USING ERRCODE='23514';END IF;
  EXECUTE format('SELECT to_jsonb(x) FROM public.%I x WHERE (tenant_id,id)=($1,$2)',wr->>'table') INTO live USING t,(wr->'row'->>'id')::uuid;
  IF live IS DISTINCT FROM wr->'row' THEN RAISE EXCEPTION 'Rzeczywisty świadek przyjęcia zmienił treść' USING ERRCODE='23514';END IF;
 END LOOP;
 -- Writer updates once per immutable arrival. Preserve original source stock,
 -- reserved quantities and unrelated bins/positions, including zero rows.
 FOR rec IN SELECT coalesce(b->>'warehouse_id',c->>'warehouse_id') warehouse_id,coalesce(b->>'product_id',c->>'product_id') product_id,b,c FROM jsonb_array_elements(a.before_snapshot->'stock')b FULL JOIN jsonb_array_elements(cur->'stock')c ON(b->>'warehouse_id',b->>'product_id')=(c->>'warehouse_id',c->>'product_id') LOOP
  cell:=NULL;SELECT value INTO cell FROM jsonb_array_elements(a.payload->'plan'->'stock_effects')x WHERE(x->>'warehouse_id',x->>'product_id')=(rec.warehouse_id,rec.product_id);
  IF cell IS NULL THEN IF rec.b IS DISTINCT FROM rec.c THEN RAISE EXCEPTION 'Zmienił się stan poza docelową unią' USING ERRCODE='23514';END IF;CONTINUE;END IF;
  SELECT count(*) INTO want_updates FROM jsonb_array_elements(a.payload->'plan'->'arrivals')x WHERE(x->>'warehouse_id',x->>'product_id')=(rec.warehouse_id,rec.product_id);
  IF rec.c IS NULL OR(rec.c->>'on_hand')::bigint IS DISTINCT FROM(cell->'after'->>'on_hand')::bigint OR(rec.c->>'reserved')::bigint IS DISTINCT FROM(cell->'after'->>'reserved')::bigint
  OR(rec.b IS NOT NULL AND rec.b-ARRAY['on_hand','available','version'] IS DISTINCT FROM rec.c-ARRAY['on_hand','available','version'])
  OR(rec.b IS NULL AND((rec.c->>'reserved')::bigint<>0 OR rec.c->>'location' IS DISTINCT FROM(SELECT x->>'location' FROM jsonb_array_elements(a.payload->'plan'->'arrivals') WITH ORDINALITY z(x,seq) WHERE(x->>'warehouse_id',x->>'product_id')=(rec.warehouse_id,rec.product_id) ORDER BY seq LIMIT 1)))
  OR(rec.c->>'version')::bigint IS DISTINCT FROM coalesce((rec.b->>'version')::bigint,0)+want_updates THEN RAISE EXCEPTION 'Zmiana docelowego zapasu nie odpowiada przyjęciu' USING ERRCODE='23514';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(a.payload->'plan'->'stock_effects')z WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cur->'stock')x WHERE(x->>'warehouse_id',x->>'product_id')=(z->>'warehouse_id',z->>'product_id'))) THEN RAISE EXCEPTION 'Brak przyjętego stanu' USING ERRCODE='23514';END IF;
 FOR rec IN SELECT coalesce(b->>'warehouse_id',c->>'warehouse_id') warehouse_id,coalesce(b->>'product_id',c->>'product_id') product_id,coalesce(b->>'location',c->>'location') location,b,c FROM jsonb_array_elements(a.before_snapshot->'stock_locations')b FULL JOIN jsonb_array_elements(cur->'stock_locations')c ON(b->>'warehouse_id',b->>'product_id',b->>'location')=(c->>'warehouse_id',c->>'product_id',c->>'location') LOOP
  SELECT coalesce(sum((x->>'quantity')::bigint),0) INTO want_qty FROM jsonb_array_elements(a.payload->'plan'->'arrivals')x WHERE(x->>'warehouse_id',x->>'product_id',x->>'location')=(rec.warehouse_id,rec.product_id,rec.location);
  IF rec.c IS NULL OR(rec.b IS NULL AND want_qty=0) OR(rec.b IS NOT NULL AND rec.b-'quantity' IS DISTINCT FROM rec.c-'quantity') OR(rec.c->>'quantity')::bigint-coalesce((rec.b->>'quantity')::bigint,0) IS DISTINCT FROM want_qty THEN RAISE EXCEPTION 'Lokalizacje nie zachowują dokładnego przyjęcia' USING ERRCODE='23514';END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('warehouse_id',x->'warehouse_id','product_id',x->'product_id','quantity',x->'quantity') ORDER BY x->>'warehouse_id',x->>'product_id',x->>'quantity'),'[]') INTO expected FROM jsonb_array_elements(a.payload->'plan'->'arrivals')x;
 SELECT coalesce(jsonb_agg(jsonb_build_object('warehouse_id',w->'row'->'warehouse_id','product_id',w->'row'->'product_id','quantity',w->'row'->'delta') ORDER BY w->'row'->>'warehouse_id',w->'row'->>'product_id',w->'row'->>'delta'),'[]') INTO actual FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='stock_movements';
 IF actual IS DISTINCT FROM expected OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='stock_movements' AND(w->'row'->>'kind' IS DISTINCT FROM 'return' OR(w->'row'->>'order_id',w->'row'->>'return_id') IS DISTINCT FROM(a.order_id::text,a.return_id::text) OR(w->'row'->>'delta')::bigint<=0)) THEN RAISE EXCEPTION 'Wymagany dokładny dziennik zwrotu każdej części' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('warehouse_id',x->'warehouse_id','product_id',x->'product_id','location',x->'location','quantity',x->'quantity') ORDER BY x->>'warehouse_id',x->>'product_id',x->>'location',x->>'quantity'),'[]') INTO expected FROM jsonb_array_elements(a.payload->'plan'->'arrivals')x;
 SELECT coalesce(jsonb_agg(jsonb_build_object('warehouse_id',w->'row'->'warehouse_id','product_id',w->'row'->'product_id','location',w->'row'->'location','quantity',w->'row'->'delta') ORDER BY w->'row'->>'warehouse_id',w->'row'->>'product_id',w->'row'->>'location',w->'row'->>'delta'),'[]') INTO actual FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='stock_location_movements';
 IF actual IS DISTINCT FROM expected OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='stock_location_movements' AND(w->'row'->>'kind' IS DISTINCT FROM 'stock_in' OR(w->'row'->>'delta')::bigint<=0 OR w->'row'->'order_id' IS DISTINCT FROM 'null'::jsonb OR w->'row'->'operation_id' IS DISTINCT FROM 'null'::jsonb)) THEN RAISE EXCEPTION 'Wymagany dokładny naturalny dziennik lokalizacji' USING ERRCODE='23514';END IF;
 IF a.payload->'planner_source'->'wms'->'enabled'='true'::jsonb AND jsonb_array_length(a.payload->'plan'->'arrivals')>0 THEN
  SELECT * INTO op FROM public.wms_operations WHERE(tenant_id,id)=(t,eid);
  expected_request:=jsonb_build_object('protocol','destinations_v1','admission_id',eid,'preview_id',a.preview_id,'return_id',a.return_id,'order_id',a.order_id,'parts',(SELECT jsonb_agg(x->'part_id' ORDER BY x->>'part_id' COLLATE "C") FROM jsonb_array_elements(a.payload->'plan'->'parts')x));
  IF op.id IS NULL OR(op.kind,op.actor_id,op.client_key,op.order_id,op.return_id,op.policy_version) IS DISTINCT FROM('return',a.actor_id,eid,a.order_id,a.return_id,(a.payload->'planner_source'->'wms'->>'policy_version')::bigint) OR op.request IS DISTINCT FROM expected_request OR op.request_hash IS DISTINCT FROM public.return_assistant_hash(expected_request)
  OR op.warehouse_document_id IS NOT NULL OR op.purchase_receipt_id IS NOT NULL
  OR(SELECT count(*) FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='wms_operations')<>1 THEN RAISE EXCEPTION 'Zwrot wymaga jednej własnej operacji WMS' USING ERRCODE='23514';END IF;
  IF jsonb_typeof(op.result) IS DISTINCT FROM 'object' OR op.result-ARRAY['fragments','legacy_unknown_layers','valuation']<>'{}' OR NOT op.result?&ARRAY['fragments','legacy_unknown_layers','valuation']
  OR jsonb_typeof(op.result->'fragments') IS DISTINCT FROM 'array' OR op.result->'legacy_unknown_layers' IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'Operacja WMS wymaga dokładnego wyniku fragmentów' USING ERRCODE='23514';END IF;
  SELECT coalesce(jsonb_agg(x-'id' ORDER BY x->>'part_id',x->>'issue_fragment_id',x->>'location'),'[]') INTO actual FROM jsonb_array_elements(op.result->'fragments')x;
  SELECT coalesce(jsonb_agg(x ORDER BY x->>'part_id',x->>'issue_fragment_id',x->>'location'),'[]') INTO expected FROM jsonb_array_elements(a.payload->'plan'->'private_fragment_effects')x;
  IF actual IS DISTINCT FROM expected OR(SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(op.result->'fragments')x)<>jsonb_array_length(op.result->'fragments')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(op.result->'fragments')x WHERE NOT EXISTS(SELECT 1 FROM public.wms_return_fragments f WHERE(f.tenant_id,f.operation_id,f.id,f.issue_fragment_id,f.product_id,f.layer_id,f.warehouse_id,f.location,f.quantity)=(t,eid,(x->>'id')::uuid,(x->>'issue_fragment_id')::uuid,(x->>'product_id')::uuid,(x->>'layer_id')::uuid,(x->>'warehouse_id')::uuid,x->>'location',(x->>'quantity')::int) AND f.value_minor IS NOT DISTINCT FROM(x->>'value_minor')::bigint)) THEN RAISE EXCEPTION 'Wynik WMS ma inne rzeczywiste fragmenty lub pochodzenie' USING ERRCODE='23514';END IF;
  SELECT jsonb_build_object('currency',a.payload->'plan'->'currency','quantity',coalesce(sum((x->>'quantity')::numeric),0)::text,'known_minor',coalesce(sum((x->>'value_minor')::numeric),0)::text,'unknown_quantity',coalesce(sum((x->>'unknown_quantity')::numeric),0)::text,'known_quantity',(coalesce(sum((x->>'quantity')::numeric),0)-coalesce(sum((x->>'unknown_quantity')::numeric),0))::text) INTO expected FROM jsonb_array_elements(a.payload->'plan'->'private_fragment_effects')x;
  IF op.result->'valuation' IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Wynik WMS ma inną oryginalną wycenę' USING ERRCODE='23514';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('issue_fragment_id',x->'issue_fragment_id','layer_id',x->'layer_id','product_id',x->'product_id','warehouse_id',x->'warehouse_id','location',x->'location','quantity',x->'quantity','value_minor',x->'value_minor') ORDER BY x->>'issue_fragment_id',x->>'warehouse_id',x->>'location',x->>'quantity'),'[]') INTO expected FROM jsonb_array_elements(a.payload->'plan'->'private_fragment_effects')x;
  SELECT coalesce(jsonb_agg(jsonb_build_object('issue_fragment_id',w->'row'->'issue_fragment_id','layer_id',w->'row'->'layer_id','product_id',w->'row'->'product_id','warehouse_id',w->'row'->'warehouse_id','location',w->'row'->'location','quantity',w->'row'->'quantity','value_minor',CASE WHEN w->'row'->'value_minor'='null'::jsonb THEN 'null'::jsonb ELSE to_jsonb(w->'row'->>'value_minor') END) ORDER BY w->'row'->>'issue_fragment_id',w->'row'->>'warehouse_id',w->'row'->>'location',w->'row'->>'quantity'),'[]') INTO actual FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='wms_return_fragments';
  IF actual IS DISTINCT FROM expected OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='wms_return_fragments' AND(w->'row'->>'operation_id',w->'row'->>'return_id',w->'row'->>'order_id') IS DISTINCT FROM(eid::text,a.return_id::text,a.order_id::text)) THEN RAISE EXCEPTION 'Fragmenty nie odpowiadają dokładnej zgodzie SALE i CUSTODY' USING ERRCODE='23514';END IF;
  FOR rec IN SELECT coalesce(b->>'warehouse_id',c->>'warehouse_id') warehouse_id,coalesce(b->>'product_id',c->>'product_id') product_id,coalesce(b->>'location',c->>'location') location,coalesce(b->>'layer_id',c->>'layer_id') layer_id,b,c FROM jsonb_array_elements(a.before_snapshot->'wms_layer_positions')b FULL JOIN jsonb_array_elements(cur->'wms_layer_positions')c ON(b->>'warehouse_id',b->>'product_id',b->>'location',b->>'layer_id')=(c->>'warehouse_id',c->>'product_id',c->>'location',c->>'layer_id') LOOP
   SELECT coalesce(sum((x->>'quantity')::bigint),0),count(*) INTO want_qty,want_updates FROM jsonb_array_elements(a.payload->'plan'->'private_fragment_effects')x WHERE(x->>'warehouse_id',x->>'product_id',x->>'location',x->>'layer_id')=(rec.warehouse_id,rec.product_id,rec.location,rec.layer_id);
   IF rec.c IS NULL OR(rec.b IS NULL AND want_qty=0) OR(rec.b IS NOT NULL AND rec.b-ARRAY['quantity','version'] IS DISTINCT FROM rec.c-ARRAY['quantity','version']) OR(rec.c->>'quantity')::bigint-coalesce((rec.b->>'quantity')::bigint,0) IS DISTINCT FROM want_qty OR(rec.c->>'version')::bigint IS DISTINCT FROM coalesce((rec.b->>'version')::bigint,0)+want_updates OR(rec.b IS NULL AND(rec.c->>'reserved')::bigint<>0) THEN RAISE EXCEPTION 'Pozycja warstwy nie zachowuje ilości lub rezerwacji' USING ERRCODE='23514';END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(jsonb_build_object('warehouse_id',x->'warehouse_id','product_id',x->'product_id','location',x->'location','layer_id',x->'layer_id','quantity',x->'quantity','value_minor',x->'value_minor') ORDER BY x->>'warehouse_id',x->>'product_id',x->>'location',x->>'layer_id',x->>'quantity'),'[]') INTO expected FROM jsonb_array_elements(a.payload->'plan'->'private_fragment_effects')x;
  SELECT coalesce(jsonb_agg(jsonb_build_object('warehouse_id',w->'row'->'warehouse_id','product_id',w->'row'->'product_id','location',w->'row'->'location','layer_id',w->'row'->'layer_id','quantity',w->'row'->'delta','value_minor',CASE WHEN w->'row'->'value_delta'='null'::jsonb THEN 'null'::jsonb ELSE to_jsonb(w->'row'->>'value_delta') END) ORDER BY w->'row'->>'warehouse_id',w->'row'->>'product_id',w->'row'->>'location',w->'row'->>'layer_id',w->'row'->>'delta'),'[]') INTO actual FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='wms_layer_movements';
  IF actual IS DISTINCT FROM expected OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table'='wms_layer_movements' AND(w->'row'->>'operation_id' IS DISTINCT FROM eid::text OR w->'row'->>'kind' IS DISTINCT FROM 'return' OR(w->'row'->>'delta')::bigint<=0)) THEN RAISE EXCEPTION 'Warstwy nie mają dokładnego dziennika przyjęcia' USING ERRCODE='23514';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(cur->'wms_issue_fragments')f WHERE(SELECT coalesce(sum((r->>'quantity')::bigint),0) FROM jsonb_array_elements(cur->'wms_return_fragments')r WHERE r->>'issue_fragment_id'=f->>'id')>(f->>'quantity')::bigint) THEN RAISE EXCEPTION '211 frozen SALE and CUSTODY exceed original issue fragment' USING ERRCODE='23514';END IF;
 ELSE
  IF cur->'wms_layer_positions' IS DISTINCT FROM a.before_snapshot->'wms_layer_positions' OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.witnesses)w WHERE w->>'table' IN('wms_operations','wms_return_fragments','wms_layer_movements')) THEN RAISE EXCEPTION 'Zwrot bez fizycznego WMS nie tworzy warstw ani kosztu' USING ERRCODE='23514';END IF;
 END IF;
END $$;

CREATE FUNCTION public.return_credit211_history148(eid uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $history211$
DECLARE
 tenant uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;
 admission public.return_destination_admissions;
 assistant_admission public.return_assistant_admissions;
 receipt public.return_assistant_receipts;
 preview public.return_assistant_previews;
 session_row public.return_assistant_sessions;
 current_return public.return_cases;
 original_request jsonb;native_plan jsonb;actual jsonb;wanted jsonb;typed_parts jsonb;typed_items jsonb;
 before_header jsonb;after_header jsonb;before_order jsonb;after_order jsonb;
 expected_result jsonb;part_row jsonb;revision public.return_destination_status_revisions;
 table_name text;key_names text[];row_count bigint;payload_bytes numeric;lineage jsonb;birth_items jsonb;financial jsonb;typed_arrivals jsonb;typed_fragments jsonb;
 snapshot_keys text[]:=ARRAY['documents','order_items','order_parcel_dispatches','order_parcel_releases','orders',
  'payment_entries','reservation_locations','reservations','return_cases','return_items','shipments','stock',
  'stock_location_movements','stock_locations','stock_movements','wms_cost_layers','wms_issue_fragments',
  'wms_layer_movements','wms_layer_positions','wms_lots','wms_operations','wms_reservation_layers','wms_return_fragments'];
BEGIN
 IF session_user<>'postgres' OR current_user<>'postgres' OR tenant IS NULL
 OR current_setting('session_replication_role')<>'origin' THEN
  RAISE EXCEPTION '211 received history requires own owner/tenant/origin' USING ERRCODE='42501';END IF;
 IF public.catalog_header205_valid() IS DISTINCT FROM true OR public.local_consumer_credit_guards() IS DISTINCT FROM true
 OR public.ordinary188_structure_valid() IS DISTINCT FROM true OR public.return_destination_guards() IS DISTINCT FROM true
 OR public.catalog_stock_return_guards() IS DISTINCT FROM true THEN
  RAISE EXCEPTION '211 received history requires unchanged complete predecessors' USING ERRCODE='55000';END IF;
 SELECT * INTO admission FROM public.return_destination_admissions WHERE(tenant_id,receipt_id)=(tenant,eid);
 SELECT * INTO receipt FROM public.return_assistant_receipts WHERE(tenant_id,id)=(tenant,eid);
 IF admission.receipt_id IS NULL OR receipt.id IS NULL OR admission.after_snapshot IS NULL
 OR admission.before_snapshot='{}'::jsonb OR admission.transaction_id=pg_current_xact_id()
 OR admission.payload->>'action' IS DISTINCT FROM 'receive'
 OR admission.payload#>>'{snapshot,protocol}' IS DISTINCT FROM 'destinations_v1' THEN
  RAISE EXCEPTION '211 requires a completed historical received148 audit' USING ERRCODE='23514';END IF;
 SELECT * INTO assistant_admission FROM public.return_assistant_admissions
  WHERE(tenant_id,transaction_id,receipt_id)=(tenant,admission.transaction_id,eid);
 SELECT * INTO preview FROM public.return_assistant_previews WHERE(tenant_id,id)=(tenant,admission.preview_id);
 SELECT * INTO session_row FROM public.return_assistant_sessions WHERE(tenant_id,id)=(tenant,admission.session_id);
 SELECT * INTO current_return FROM public.return_cases WHERE(tenant_id,id)=(tenant,admission.return_id);
 IF assistant_admission.receipt_id IS NULL OR preview.id IS NULL OR session_row.id IS NULL OR current_return.id IS NULL
 OR(receipt.preview_id,receipt.session_id,receipt.return_id,receipt.order_id,receipt.actor_id,receipt.api_key_id,receipt.client_key,receipt.request_hash,receipt.payload)
  IS DISTINCT FROM(admission.preview_id,admission.session_id,admission.return_id,admission.order_id,admission.actor_id,admission.api_key_id,admission.client_key,admission.request_hash,admission.payload)
 OR(assistant_admission.preview_id,assistant_admission.session_id,assistant_admission.return_id,assistant_admission.actor_id,assistant_admission.api_key_id,assistant_admission.client_key,assistant_admission.request_hash,assistant_admission.payload)
  IS DISTINCT FROM(admission.preview_id,admission.session_id,admission.return_id,admission.actor_id,admission.api_key_id,admission.client_key,admission.request_hash,admission.payload)
 OR(preview.session_id,preview.return_id,preview.order_id,preview.actor_id,preview.api_key_id,preview.payload,preview.scope_hash)
  IS DISTINCT FROM(admission.session_id,admission.return_id,admission.order_id,admission.actor_id,admission.api_key_id,admission.payload,receipt.scope_hash)
 OR(session_row.return_id,session_row.order_id,session_row.actor_id,session_row.api_key_id,session_row.state)
  IS DISTINCT FROM(admission.return_id,admission.order_id,admission.actor_id,admission.api_key_id,'completed'::text)
 OR session_row.version IS DISTINCT FROM(admission.payload#>>'{snapshot,session,version}')::bigint+1
 OR(session_row.station_id::text,session_row.station,session_row.scanned)
  IS DISTINCT FROM(admission.payload#>>'{snapshot,session,station_id}',admission.payload#>'{snapshot,session,station}',admission.payload#>'{snapshot,scanned}')
 OR receipt.scope_hash IS DISTINCT FROM public.return_assistant_hash(admission.payload||jsonb_build_object('private_scope_nonce',preview.private_scope_nonce))
 OR admission.request_hash IS DISTINCT FROM public.return_assistant_hash(jsonb_build_object('tenant_id',tenant,'preview_id',preview.id,'kind','destinations_receive','request',admission.request,'actor_id',admission.actor_id,'api_key_id',admission.api_key_id))
 OR admission.request IS DISTINCT FROM jsonb_build_object('client_key',admission.client_key,'scope_hash',preview.scope_hash,'confirmed',true,'lease_token',admission.request->'lease_token')
 OR receipt.created_at<admission.opened_at OR admission.opened_at<preview.created_at OR admission.opened_at>=preview.expires_at THEN
  RAISE EXCEPTION '211 received preview/admission/session/result lineage differs' USING ERRCODE='23514';END IF;

 -- Bounds precede every full-array comparison; no truncation or sampled proof.
 payload_bytes:=pg_column_size(admission.payload)::numeric+pg_column_size(admission.before_snapshot)
  +pg_column_size(admission.after_snapshot)+pg_column_size(receipt.result)+pg_column_size(session_row.source)
  +pg_column_size(assistant_admission.witnesses)+pg_column_size(admission.witnesses);
 IF payload_bytes>33554432 THEN RAISE EXCEPTION '207 complete rejected audit exceeds budget' USING ERRCODE='54000';END IF;
 IF(SELECT count(*) FROM public.return_destination_arrivals WHERE(tenant_id,receipt_id)=(tenant,eid))>10000
 OR(SELECT count(*) FROM public.return_destination_fragments WHERE(tenant_id,receipt_id)=(tenant,eid))>10000
 OR(SELECT count(*) FROM public.return_destination_parts WHERE(tenant_id,receipt_id)=(tenant,eid))>10000
 OR(SELECT count(*) FROM public.return_items WHERE(tenant_id,return_id)=(tenant,admission.return_id))>100
 OR(SELECT count(*) FROM public.return_assistant_photos WHERE(tenant_id,session_id)=(tenant,admission.session_id))>10000 THEN
  RAISE EXCEPTION '207 complete native rejected rows exceed budget' USING ERRCODE='54000';END IF;
 IF jsonb_typeof(admission.before_snapshot) IS DISTINCT FROM 'object' OR jsonb_typeof(admission.after_snapshot) IS DISTINCT FROM 'object'
 OR jsonb_typeof(admission.witnesses) IS DISTINCT FROM 'array' OR jsonb_typeof(assistant_admission.witnesses) IS DISTINCT FROM 'array' OR jsonb_array_length(admission.witnesses)>10000 OR jsonb_array_length(assistant_admission.witnesses)>10000 THEN
  RAISE EXCEPTION '211 received inspection cannot have physical witnesses' USING ERRCODE='23514';END IF;
 SELECT array_agg(k ORDER BY k COLLATE "C") INTO key_names FROM jsonb_object_keys(admission.before_snapshot)k;
 IF key_names IS DISTINCT FROM snapshot_keys THEN RAISE EXCEPTION '207 complete before snapshot required' USING ERRCODE='23514';END IF;
 SELECT array_agg(k ORDER BY k COLLATE "C") INTO key_names FROM jsonb_object_keys(admission.after_snapshot)k;
 IF key_names IS DISTINCT FROM snapshot_keys THEN RAISE EXCEPTION '207 complete after snapshot required' USING ERRCODE='23514';END IF;
 FOREACH table_name IN ARRAY snapshot_keys LOOP
  IF jsonb_typeof(admission.before_snapshot->table_name) IS DISTINCT FROM 'array'
  OR jsonb_typeof(admission.after_snapshot->table_name) IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION '207 typed complete snapshot arrays required' USING ERRCODE='23514';END IF;
  IF jsonb_array_length(admission.before_snapshot->table_name)>10000 OR jsonb_array_length(admission.after_snapshot->table_name)>10000 THEN
   RAISE EXCEPTION '207 complete rejected rows exceed budget' USING ERRCODE='54000';END IF;
  IF EXISTS(SELECT FROM jsonb_array_elements(admission.before_snapshot->table_name)entry WHERE entry->>'tenant_id' IS DISTINCT FROM tenant::text)
  OR EXISTS(SELECT FROM jsonb_array_elements(admission.after_snapshot->table_name)entry WHERE entry->>'tenant_id' IS DISTINCT FROM tenant::text) THEN
   RAISE EXCEPTION '211 received snapshot contains foreign rows' USING ERRCODE='23514';END IF;
  -- Validate every full typed column; jsonb_populate_recordset rejects bad types,
  -- and this equality rejects missing/extra fields, before any birth comparison.
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(v) ORDER BY to_jsonb(v)::text),''[]'') FROM jsonb_populate_recordset(NULL::public.%I,$1)v',table_name) INTO actual USING admission.before_snapshot->table_name;
  SELECT coalesce(jsonb_agg(v ORDER BY v::text),'[]') INTO wanted FROM jsonb_array_elements(admission.before_snapshot->table_name)v;
  IF actual IS DISTINCT FROM wanted THEN RAISE EXCEPTION '211 before snapshot full typed fields differ' USING ERRCODE='23514';END IF;
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(v) ORDER BY to_jsonb(v)::text),''[]'') FROM jsonb_populate_recordset(NULL::public.%I,$1)v',table_name) INTO actual USING admission.after_snapshot->table_name;
  SELECT coalesce(jsonb_agg(v ORDER BY v::text),'[]') INTO wanted FROM jsonb_array_elements(admission.after_snapshot->table_name)v;
  IF actual IS DISTINCT FROM wanted THEN RAISE EXCEPTION '211 after snapshot full typed fields differ' USING ERRCODE='23514';END IF;
 END LOOP;

 IF EXISTS(SELECT FROM public.catalog_stock_return_admissions ca WHERE(ca.tenant_id,ca.return_id)=(tenant,admission.return_id))
 OR EXISTS(SELECT FROM public.catalog_stock_return_receipts cr WHERE(cr.tenant_id,cr.return_id)=(tenant,admission.return_id) OR(cr.tenant_id,cr.assistant_receipt_id)=(tenant,eid))
 OR EXISTS(SELECT FROM public.catalog_stock_control_effect_admissions ce WHERE(ce.tenant_id,ce.source_kind,ce.source_id)=(tenant,'return',admission.return_id)) THEN
  RAISE EXCEPTION '211148-only cannot borrow or bypass169/152 lineage' USING ERRCODE='23514';END IF;
 -- Rebuild the native plan from the captured birth source and original request,
 -- without renewing a lease or using today's active status/policy/prices/stock.
 original_request:=admission.payload#>'{snapshot,request}'||jsonb_build_object('client_key',preview.client_key,'lease_token',admission.request->'lease_token');
 IF preview.request_hash IS DISTINCT FROM public.return_assistant_hash(jsonb_build_object('tenant_id',tenant,'session_id',preview.session_id,'kind','destinations_preview','actor_id',preview.actor_id,'api_key_id',preview.api_key_id,'request',original_request)) THEN
  RAISE EXCEPTION '211 received original preview request differs' USING ERRCODE='23514';END IF;
 native_plan:=public.return_destination_plan(admission.payload->'planner_source',original_request);
 IF native_plan IS DISTINCT FROM admission.payload->'plan' OR native_plan IS DISTINCT FROM admission.payload#>'{snapshot,plan}'
 OR(native_plan->>'return_id',native_plan->>'order_id') IS DISTINCT FROM(admission.return_id::text,admission.order_id::text)
 OR(native_plan#>>'{summary,accepted}')::bigint<=0 THEN
  RAISE EXCEPTION '211 complete original receive plan differs' USING ERRCODE='23514';END IF;
 IF admission.payload->'receive_input' IS DISTINCT FROM jsonb_build_object('version',(original_request->>'return_version')::bigint,
  'note',original_request->>'note','shipping_refund',original_request->'shipping_refund','items',
  (SELECT jsonb_agg(part-ARRAY['custody','rejected','refund_minor'] ORDER BY part->>'item_id') FROM jsonb_array_elements(native_plan->'decisions')part))
 OR admission.payload->'summary' IS DISTINCT FROM(native_plan->'summary'||jsonb_build_object('refund_minor',native_plan#>'{summary,commercial_credit_minor}','shipping_refund',native_plan#>'{summary,shipping_refund_minor}')) THEN
  RAISE EXCEPTION '211 exact received core request or summary differs' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(typed_part) ORDER BY typed_part.id),'[]') INTO actual
  FROM public.return_destination_parts typed_part WHERE(typed_part.tenant_id,typed_part.receipt_id)=(tenant,eid);
 SELECT coalesce(jsonb_agg(jsonb_build_object('tenant_id',tenant,'id',(part->>'part_id')::uuid,'receipt_id',eid,
  'preview_id',admission.preview_id,'session_id',admission.session_id,'return_id',admission.return_id,'order_id',admission.order_id,
  'item_id',(part->>'item_id')::uuid,'quantity',(part->>'quantity')::integer,'status_id',(part#>>'{status,status_id}')::uuid,
  'status_version',(part#>>'{status,version}')::bigint,'status_revision_id',(part#>>'{status,revision_id}')::uuid,
  'decision',part#>>'{status,decision}','effect',part#>>'{status,inventory_effect}',
  'warehouse_id',(part#>>'{status,warehouse_id}')::uuid,'warehouse_policy_version',(part#>>'{status,warehouse_policy_version}')::bigint,
  'refund_minor',(part->>'refund_minor')::bigint,'snapshot',part) ORDER BY(part->>'part_id')::uuid),'[]')
 INTO wanted FROM jsonb_array_elements(native_plan->'parts')part;
 IF actual IS DISTINCT FROM wanted THEN RAISE EXCEPTION '211 exact typed received parts differ' USING ERRCODE='23514';END IF;
 typed_parts:=actual;
 FOR part_row IN SELECT value FROM jsonb_array_elements(native_plan->'parts') LOOP
  SELECT * INTO revision FROM public.return_destination_status_revisions
   WHERE(tenant_id,status_id,id,version)=(tenant,(part_row#>>'{status,status_id}')::uuid,(part_row#>>'{status,revision_id}')::uuid,(part_row#>>'{status,version}')::bigint);
  IF revision.id IS NULL OR part_row->'status' IS DISTINCT FROM jsonb_build_object('status_id',revision.status_id,'version',revision.version::text,
   'revision_id',revision.id,'active',revision.settings->'active','name',revision.settings->'name','color',revision.settings->'color',
   'decision',revision.settings->'decision','inventory_effect',revision.settings->'inventory_effect','warehouse_id',revision.settings->'warehouse_id',
   'warehouse_policy_version',revision.settings->'warehouse_policy_version','default_location',revision.settings->'default_location') THEN
   RAISE EXCEPTION '211 received immutable status revision differs' USING ERRCODE='23514';END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]') INTO actual
 FROM public.return_destination_arrivals x WHERE(x.tenant_id,x.receipt_id)=(tenant,admission.receipt_id);
 SELECT coalesce(jsonb_agg(jsonb_build_object('tenant_id',tenant,'id',public.return_destination_identity(admission.receipt_id,'arrival:'||(x->>'part_id')||':'||(x->>'product_id')),
  'receipt_id',admission.receipt_id,'part_id',(x->>'part_id')::uuid,'return_id',admission.return_id,'order_id',admission.order_id,'item_id',(x->>'item_id')::uuid,
  'product_id',(x->>'product_id')::uuid,'warehouse_id',(x->>'warehouse_id')::uuid,'location',x->>'location','quantity',(x->>'quantity')::integer,'effect',x->>'effect')
  ORDER BY public.return_destination_identity(admission.receipt_id,'arrival:'||(x->>'part_id')||':'||(x->>'product_id'))),'[]')
 INTO wanted FROM jsonb_array_elements(native_plan->'arrivals')x;
 IF actual IS DISTINCT FROM wanted THEN RAISE EXCEPTION '211 full typed arrivals differ' USING ERRCODE='23514';END IF;
 -- Every native fragment is a typed member of one arrival; compare bags to
 -- retain multiplicity when several parts share an original issue fragment.
 SELECT coalesce(jsonb_agg(to_jsonb(v) ORDER BY to_jsonb(v)::text),'[]') INTO actual FROM(
  SELECT df.part_id::text part_id,df.item_id::text item_id,df.product_id::text product_id,df.warehouse_id::text warehouse_id,
   df.location,df.quantity,df.effect,df.issue_fragment_id::text issue_fragment_id,df.layer_id::text layer_id,
   l.unit_cost_minor::text unit_cost_minor,f.value_minor::text value_minor,CASE WHEN l.unit_cost_minor IS NULL THEN df.quantity ELSE 0 END unknown_quantity,l.currency
  FROM public.return_destination_fragments df
  JOIN public.wms_return_fragments f ON(f.tenant_id,f.id,f.operation_id,f.return_id,f.order_id,f.issue_fragment_id,f.product_id,f.layer_id,f.warehouse_id,f.location,f.quantity)
   =(df.tenant_id,df.fragment_id,df.receipt_id,df.return_id,df.order_id,df.issue_fragment_id,df.product_id,df.layer_id,df.warehouse_id,df.location,df.quantity)
  JOIN public.wms_cost_layers l ON(l.tenant_id,l.id,l.product_id)=(f.tenant_id,f.layer_id,f.product_id)
  JOIN public.return_destination_arrivals arrival ON(arrival.tenant_id,arrival.id,arrival.receipt_id,arrival.part_id,arrival.return_id,arrival.order_id,arrival.item_id,arrival.product_id,arrival.warehouse_id,arrival.location,arrival.effect)
   =(df.tenant_id,df.arrival_id,df.receipt_id,df.part_id,df.return_id,df.order_id,df.item_id,df.product_id,df.warehouse_id,df.location,df.effect)
  WHERE(df.tenant_id,df.receipt_id)=(tenant,admission.receipt_id))v;
 SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO wanted FROM jsonb_array_elements(native_plan->'private_fragment_effects')x;
 IF actual IS DISTINCT FROM wanted
 OR(SELECT count(*) FROM public.return_destination_fragments WHERE(tenant_id,receipt_id)=(tenant,admission.receipt_id))<>jsonb_array_length(wanted)
 OR EXISTS(SELECT FROM public.wms_return_fragments f WHERE(f.tenant_id,f.return_id)=(tenant,admission.return_id)
  AND NOT EXISTS(SELECT FROM public.return_destination_fragments df WHERE(df.tenant_id,df.receipt_id,df.fragment_id)=(tenant,admission.receipt_id,f.id))) THEN
  RAISE EXCEPTION '211 full native WMS fragment bijection differs' USING ERRCODE='23514';END IF;
 PERFORM public.return_credit211_frozen_physical(eid);
 SELECT count(*) INTO row_count FROM jsonb_array_elements(admission.before_snapshot->'return_cases')entry WHERE entry->>'id'=admission.return_id::text;
 IF row_count<>1 THEN RAISE EXCEPTION '211 one before return required' USING ERRCODE='23514';END IF;
 SELECT entry INTO before_header FROM jsonb_array_elements(admission.before_snapshot->'return_cases')entry WHERE entry->>'id'=admission.return_id::text;
 SELECT count(*) INTO row_count FROM jsonb_array_elements(admission.after_snapshot->'return_cases')entry WHERE entry->>'id'=admission.return_id::text;
 IF row_count<>1 THEN RAISE EXCEPTION '211 one after return required' USING ERRCODE='23514';END IF;
 SELECT entry INTO after_header FROM jsonb_array_elements(admission.after_snapshot->'return_cases')entry WHERE entry->>'id'=admission.return_id::text;
 IF(before_header->>'order_id',before_header->>'state',before_header->>'remedy',before_header->>'legacy') IS DISTINCT FROM(admission.order_id::text,'requested','refund','false')
 OR before_header->'received_at' IS DISTINCT FROM 'null'::jsonb OR before_header->'receipt' IS DISTINCT FROM 'null'::jsonb
 OR before_header->>'receipt_sequence' IS DISTINCT FROM '0' OR before_header->>'refund_amount' IS DISTINCT FROM '0' OR before_header->>'refunded_shipping' IS DISTINCT FROM '0'
 OR admission.payload#>'{snapshot,return_case}' IS DISTINCT FROM before_header
 OR after_header->>'state' IS DISTINCT FROM 'refund_pending'
 OR current_return.state NOT IN('refund_pending','closed') OR current_return.version<(after_header->>'version')::bigint
 OR to_jsonb(current_return)-ARRAY['state','version','updated_at','refunded_at','settlement'] IS DISTINCT FROM after_header-ARRAY['state','version','updated_at','refunded_at','settlement']
 OR(after_header->>'received_at')::timestamptz>receipt.created_at THEN
  RAISE EXCEPTION '211 immutable received birth/current lifecycle differs' USING ERRCODE='23514';END IF;
 expected_result:=jsonb_build_object('state',after_header->'state','version',after_header->>'version','refund_amount',after_header->'refund_amount',
  'refunded_shipping',after_header->'refunded_shipping','received_at',after_header->'received_at','receipt',after_header->'receipt',
  'decision_note',after_header->'decision_note','id',after_header->'id','number',after_header->'number','receipt_sequence',after_header->'receipt_sequence');
 IF receipt.result IS DISTINCT FROM expected_result THEN RAISE EXCEPTION '211 full original assistant result differs' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(typed_item) ORDER BY typed_item.item_id),'[]') INTO actual FROM public.return_items typed_item WHERE(typed_item.tenant_id,typed_item.return_id)=(tenant,admission.return_id);
 SELECT coalesce(jsonb_agg(entry ORDER BY entry->>'item_id'),'[]') INTO wanted FROM jsonb_array_elements(admission.after_snapshot->'return_items')entry WHERE entry->>'return_id'=admission.return_id::text;
 IF actual IS DISTINCT FROM wanted OR jsonb_array_length(actual) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION '211 full original received items differ' USING ERRCODE='23514';END IF;
 birth_items:=actual;
 IF jsonb_array_length(admission.before_snapshot->'orders')<>1 OR jsonb_array_length(admission.after_snapshot->'orders')<>1 THEN RAISE EXCEPTION '211 one complete order birth required' USING ERRCODE='23514';END IF;
 before_order:=admission.before_snapshot->'orders'->0;after_order:=admission.after_snapshot->'orders'->0;
 SELECT jsonb_build_object('id',before_order->'id','number',before_order->'number','version',before_order->>'version',
  'status',before_order->'status','warehouse_id',before_order->'warehouse_id','currency',before_order->'currency',
  'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',entry->'id','product_id',entry->'product_id','sku',entry->'sku',
   'name',entry->'name','quantity',entry->'quantity','line_total',entry->'line_total','vat',entry->'vat','components',entry->'components')
   ORDER BY(entry->>'id')::uuid),'[]') FROM jsonb_array_elements(admission.before_snapshot->'order_items')entry),
  'wms_lots_enabled',admission.payload#>'{planner_source,wms,enabled}') INTO wanted;
 IF admission.payload#>'{snapshot,order}' IS DISTINCT FROM wanted
 OR admission.payload#>'{planner_source,wms,enabled}' IS DISTINCT FROM coalesce(admission.payload#>'{snapshot,source,wms_policy,enabled}','false'::jsonb) THEN
  RAISE EXCEPTION '211 received captured order/WMS source differs from birth' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',historical_item->'item_id','product_id',historical_order_item->'product_id',
  'sku',historical_item->'sku','name',historical_item->'name','requested',historical_item->'requested',
  'original_quantity',historical_order_item->'quantity','line_total',historical_order_item->'line_total',
  'components',historical_item->'components','ordinal',historical_ordinal) ORDER BY historical_item->>'item_id'),'[]') INTO wanted
 FROM(SELECT historical_item,historical_order_item,row_number() OVER(ORDER BY historical_item->>'item_id')::int historical_ordinal
  FROM jsonb_array_elements(admission.before_snapshot->'return_items')historical_item
  JOIN jsonb_array_elements(admission.before_snapshot->'order_items')historical_order_item
   ON historical_order_item->>'id'=historical_item->>'item_id'
  WHERE historical_item->>'return_id'=admission.return_id::text)original_lines;
 SELECT coalesce(jsonb_agg(entry-'codes' ORDER BY entry->>'item_id'),'[]') INTO actual
  FROM jsonb_array_elements(admission.payload#>'{snapshot,lines}')entry;
 IF actual IS DISTINCT FROM wanted THEN RAISE EXCEPTION '211 received captured original lines differ from birth' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(entry-'codes' ORDER BY entry->>'item_id'),'[]') INTO actual
  FROM jsonb_array_elements(session_row.source->'lines')entry;
 IF actual IS DISTINCT FROM wanted THEN RAISE EXCEPTION '211 received original session lines differ from birth' USING ERRCODE='23514';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',photo.id,'item_id',photo.item_id,'part_id',photo.part_id,'mime',photo.mime,
  'byte_count',photo.byte_count,'sha256',photo.sha256,'width',photo.width,'height',photo.height,'created_at',photo.created_at) ORDER BY photo.id),'[]') INTO actual
  FROM public.return_assistant_photos photo WHERE(photo.tenant_id,photo.session_id)=(tenant,session_row.id);
 IF actual IS DISTINCT FROM admission.payload#>'{snapshot,photos}' THEN RAISE EXCEPTION '211 received original photo evidence differs' USING ERRCODE='23514';END IF;
 IF admission.payload#>>'{snapshot,source,financial_hash}' IS DISTINCT FROM public.return_assistant_hash(jsonb_build_object(
  'payments',(SELECT coalesce(jsonb_agg(entry ORDER BY(entry->>'id')::uuid),'[]') FROM jsonb_array_elements(admission.before_snapshot->'payment_entries')entry),
  'documents',(SELECT coalesce(jsonb_agg(entry ORDER BY(entry->>'id')::uuid),'[]') FROM jsonb_array_elements(admission.before_snapshot->'documents')entry))) THEN
  RAISE EXCEPTION '211 received source financial birth differs' USING ERRCODE='23514';END IF;

 FOREACH table_name IN ARRAY ARRAY['stock_movements','stock_location_movements','wms_layer_movements','wms_return_fragments','wms_issue_fragments','wms_operations','wms_cost_layers','wms_lots'] LOOP
  SELECT coalesce(jsonb_agg(entry ORDER BY(entry->>'id')::uuid),'[]') INTO wanted FROM jsonb_array_elements(admission.after_snapshot->table_name)entry;
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(native_row) ORDER BY native_row.id),''[]'') FROM public.%I native_row WHERE native_row.tenant_id=$1 AND native_row.id IN(SELECT(entry->>''id'')::uuid FROM jsonb_array_elements($2)entry)',table_name) INTO actual USING tenant,admission.after_snapshot->table_name;
  IF actual IS DISTINCT FROM wanted THEN RAISE EXCEPTION '211 complete immutable birth journal differs' USING ERRCODE='23514';END IF;
 END LOOP;
 financial:=jsonb_build_object('return_id',admission.return_id,'receipt_id',eid,'receipt_sequence',(after_header->>'receipt_sequence')::integer,
  'received_at',to_char((after_header->>'received_at')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'refund_amount_minor',after_header->>'refund_amount','refunded_shipping_minor',after_header->>'refunded_shipping',
  'items',(SELECT jsonb_agg(jsonb_build_object('item_id',entry->'item_id','accepted',(entry->>'accepted')::bigint::text,
   'restocked',(entry->>'restocked')::bigint::text,'refund_amount_minor',(entry->>'refund_amount')::bigint::text) ORDER BY entry->>'item_id') FROM jsonb_array_elements(birth_items)entry));
 lineage:=jsonb_build_object('admission',to_jsonb(admission),'assistant_admission',to_jsonb(assistant_admission),'preview',to_jsonb(preview),
  'receipt',to_jsonb(receipt),'completed_session',to_jsonb(session_row),'plan',native_plan,'received_birth',after_header,'items',birth_items);
 RETURN jsonb_build_object('family','destinations148','tenant_id',tenant,'id',eid,'order_id',admission.order_id,'return_id',admission.return_id,
  'receipt_sequence',(after_header->>'receipt_sequence')::integer,'financial',financial||jsonb_build_object('financial_hash',public.return_credit206_hash(financial)),
  'evidence_hash',public.return_credit206_hash(lineage));
END $history211$;

CREATE TABLE public.return_credit211_acceptances(
 tenant_id uuid NOT NULL REFERENCES public.tenants,id uuid NOT NULL,order_id uuid NOT NULL,return_id uuid NOT NULL,
 family text NOT NULL CHECK(family IN('catalog169','destinations148')),
 catalog_receipt_id uuid,destination_receipt_id uuid,receipt_sequence integer NOT NULL CHECK(receipt_sequence BETWEEN 1 AND 1000),
 financial jsonb NOT NULL,evidence_hash text NOT NULL CHECK(evidence_hash~'^[a-f0-9]{64}$'),
 credit_admission_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,return_id),UNIQUE(tenant_id,order_id,receipt_sequence),
 FOREIGN KEY(tenant_id,order_id,return_id) REFERENCES public.return_cases(tenant_id,order_id,id),
 FOREIGN KEY(tenant_id,catalog_receipt_id) REFERENCES public.catalog_stock_return_receipts(tenant_id,id),
 FOREIGN KEY(tenant_id,destination_receipt_id) REFERENCES public.return_destination_admissions(tenant_id,receipt_id),
 FOREIGN KEY(tenant_id,credit_admission_id) REFERENCES public.return_credit206_admissions(tenant_id,id),
 CHECK((family='catalog169' AND catalog_receipt_id IS NOT NULL AND id=catalog_receipt_id AND destination_receipt_id IS NULL)
    OR(family='destinations148' AND destination_receipt_id IS NOT NULL AND id=destination_receipt_id AND catalog_receipt_id IS NULL)),
 CHECK(octet_length(financial::text)<=2097152)
);
CREATE INDEX return_credit211_acceptance_catalog ON public.return_credit211_acceptances(tenant_id,catalog_receipt_id);
CREATE INDEX return_credit211_acceptance_destination ON public.return_credit211_acceptances(tenant_id,destination_receipt_id);
CREATE INDEX return_credit211_acceptance_credit ON public.return_credit211_acceptances(tenant_id,credit_admission_id);
ALTER TABLE public.return_credit211_acceptances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.return_credit211_acceptances FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_scope ON public.return_credit211_acceptances TO CURRENT_USER USING(true) WITH CHECK(true);
REVOKE ALL ON public.return_credit211_acceptances FROM PUBLIC,dyna_app;

-- READ ONLY: choose one concrete original family, never a caller-supplied mode.
-- Any partial169 refuses; it cannot fall through to a less strict proof.
CREATE FUNCTION public.return_credit211_acceptance(oid uuid,rid uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $accept211$
DECLARE tenant uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;rr public.catalog_stock_return_receipts;
 ca public.catalog_stock_return_admissions;da public.return_destination_admissions;f jsonb;protocol text;
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR tenant IS NULL OR current_setting('session_replication_role')<>'origin' THEN
  RAISE EXCEPTION '211 private owner tenant origin required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT FROM public.return_cases rc WHERE(rc.tenant_id,rc.order_id,rc.id)=(tenant,oid,rid)) THEN
  RAISE EXCEPTION '211 own original return required' USING ERRCODE='P0002';END IF;
 SELECT * INTO rr FROM public.catalog_stock_return_receipts WHERE(tenant_id,return_id)=(tenant,rid);
 SELECT * INTO ca FROM public.catalog_stock_return_admissions WHERE(tenant_id,return_id)=(tenant,rid);
 IF rr.id IS NOT NULL OR ca.id IS NOT NULL THEN
  IF rr.id IS NULL OR ca.id IS NULL OR NOT ca.sealed OR(rr.id,rr.order_id,ca.order_id) IS DISTINCT FROM(ca.id,oid,oid) THEN
   RAISE EXCEPTION '211 partial or foreign169 cannot fall back to148' USING ERRCODE='23514';END IF;
  PERFORM public.return_credit206_physical_history(rr.id);
  protocol:=ca.protocol;
  IF protocol NOT IN('rma','assistant_v1','destinations_v1') THEN RAISE EXCEPTION '211 unsupported original169 family' USING ERRCODE='23514';END IF;
  f:=jsonb_build_object('return_id',rid,'receipt_id',rr.id,'receipt_sequence',(rr.snapshot#>>'{return_case,receipt_sequence}')::integer,
   'received_at',to_char((rr.snapshot#>>'{return_case,received_at}')::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'refund_amount_minor',rr.snapshot#>>'{return_case,refund_amount}','refunded_shipping_minor',rr.snapshot#>>'{return_case,refunded_shipping}',
   'items',(SELECT coalesce(jsonb_agg(jsonb_build_object('item_id',entry->'item_id','accepted',(entry->>'accepted')::bigint::text,
    'restocked',(entry->>'restocked')::bigint::text,'refund_amount_minor',(entry->>'refund_amount')::bigint::text) ORDER BY entry->>'item_id'),'[]') FROM jsonb_array_elements(rr.snapshot->'items')entry));
  RETURN jsonb_build_object('family','catalog169','protocol',protocol,'tenant_id',tenant,'id',rr.id,'order_id',oid,'return_id',rid,
   'receipt_sequence',(rr.snapshot#>>'{return_case,receipt_sequence}')::integer,'financial',f||jsonb_build_object('financial_hash',public.return_credit206_hash(f)),
   'evidence_hash',public.return_credit206_hash(jsonb_build_object('admission',to_jsonb(ca),'receipt',to_jsonb(rr))));
 END IF;
 SELECT * INTO da FROM public.return_destination_admissions WHERE(tenant_id,order_id,return_id)=(tenant,oid,rid);
 IF da.receipt_id IS NULL THEN RAISE EXCEPTION '211 no concrete original native acceptance' USING ERRCODE='23514';END IF;
 RETURN public.return_credit211_history148(da.receipt_id)||jsonb_build_object('protocol','destinations_v1');
END $accept211$;

CREATE FUNCTION public.return_credit211_source(did uuid,selected_return uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $$
DECLARE t uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;d documents;ir local_invoice_receipts;o orders;rc record;rr catalog_stock_return_receipts; financial jsonb;acceptance211 jsonb;inspection_row record;rejectedj jsonb:='[]';acceptances jsonb:='[]';previousj jsonb:='[]';protocols jsonb:='[]';families jsonb:='[]';cr record;prev uuid;seq integer:=0;resultj jsonb;BEGIN
 PERFORM public.local_invoice_locks();SELECT * INTO d FROM public.documents WHERE(tenant_id,id)=(t,did);
 IF d.id IS NULL OR d.kind<>'invoice' OR d.mode<>'local_invoice' THEN RAISE EXCEPTION 'Brak prawdziwej FV157' USING ERRCODE='P0002';END IF;
 SELECT * INTO o FROM public.orders WHERE(tenant_id,id)=(t,d.order_id) FOR UPDATE;
 IF NOT EXISTS(SELECT FROM public.catalog_stock_return_receipts native_receipt JOIN public.catalog_stock_return_admissions aa ON(aa.tenant_id,aa.id)=(native_receipt.tenant_id,native_receipt.id) WHERE(native_receipt.tenant_id,native_receipt.order_id)=(t,o.id) AND aa.protocol='destinations_v1' AND aa.sealed) AND NOT EXISTS(SELECT FROM public.return_destination_admissions rejected_admission WHERE(rejected_admission.tenant_id,rejected_admission.order_id)=(t,o.id) AND rejected_admission.after_snapshot IS NOT NULL AND rejected_admission.payload->>'action' IN('receive','reject') AND rejected_admission.payload#>>'{snapshot,protocol}'='destinations_v1') THEN RAISE EXCEPTION 'Destination successor requires actual received destinations history' USING ERRCODE='23514';END IF;
 SELECT * INTO ir FROM public.local_invoice_receipts WHERE(tenant_id,document_id)=(t,d.id);
 IF ir.id IS NULL OR(d.order_id,d.number) IS DISTINCT FROM(ir.order_id,ir.number)
 OR d.data IS DISTINCT FROM(ir.snapshot||jsonb_build_object('number',ir.number,'preview_id',ir.preview_id,'scope_hash',ir.scope_hash,'local_only',true,'ksef_state','not_submitted','fiscalized',false))
 OR ir.scope_hash IS DISTINCT FROM public.local_invoice_hash(ir.snapshot) OR ir.snapshot->>'currency'<>'PLN' OR ir.snapshot#>>'{buyer,kind}'<>'consumer'
 OR ir.snapshot#>>'{buyer,address,country}'<>'PL' OR ir.snapshot->>'tax_regime'<>'ordinary_domestic' OR ir.snapshot->>'rounding_method'<>'gross_line_half_up'
 OR o.currency<>'PLN' OR o.fulfillment_kind<>'sale' THEN RAISE EXCEPTION 'Obcy original157 snapshot207' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT FROM documents x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,'correction')) OR EXISTS(SELECT FROM invoice_plans x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,'correction') AND x.state NOT IN('preview','cancelled')) THEN RAISE EXCEPTION 'Istniejąca inna korekta wymaga odrębnego uzgodnienia' USING ERRCODE='23514';END IF;
 IF(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 OR (SELECT coalesce(sum(pg_column_size(payload_return.snapshot)),0) FROM public.catalog_stock_return_receipts payload_return WHERE(payload_return.tenant_id,payload_return.order_id)=(t,o.id))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.return_credit206_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.local_consumer_credit_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+pg_column_size(ir.snapshot)+(SELECT coalesce(sum(pg_column_size(da.payload)::numeric+pg_column_size(da.before_snapshot)+pg_column_size(da.after_snapshot)+pg_column_size(da.witnesses)+pg_column_size(ar.result)),0) FROM public.return_destination_admissions da JOIN public.return_assistant_receipts ar ON(ar.tenant_id,ar.id)=(da.tenant_id,da.receipt_id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>'action' IN('receive','reject'))+(SELECT coalesce(sum(pg_column_size(parent211)),0) FROM public.return_credit211_acceptances parent211 WHERE(parent211.tenant_id,parent211.order_id)=(t,o.id))>33554432 THEN RAISE EXCEPTION 'Limit pełnej historii207' USING ERRCODE='54000';END IF;
 FOR inspection_row IN SELECT ar.id FROM public.return_assistant_receipts ar JOIN public.return_destination_admissions da ON(da.tenant_id,da.receipt_id)=(ar.tenant_id,ar.id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>'action'='reject' AND da.payload#>>'{snapshot,protocol}'='destinations_v1' ORDER BY ar.created_at,ar.id LOOP
  IF jsonb_array_length(rejectedj)>=1000 THEN RAISE EXCEPTION 'Complete rejected inspection budget' USING ERRCODE='54000';END IF;
  rejectedj:=rejectedj||jsonb_build_array(public.return_credit206_rejected_history(inspection_row.id));
 END LOOP;
 IF jsonb_array_length(rejectedj)+(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 THEN RAISE EXCEPTION 'Complete physical audit budget' USING ERRCODE='54000';END IF;
 FOR rc IN SELECT * FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL ORDER BY receipt_sequence,id FOR SHARE LOOP
  seq:=seq+1;
  IF rc.legacy OR rc.remedy<>'refund' OR rc.state NOT IN('refund_pending','closed') OR rc.receipt_sequence<>seq THEN RAISE EXCEPTION 'Nieobsługiwany lub niepełny ciąg RMA207' USING ERRCODE='23514';END IF;
  acceptance211:=public.return_credit211_acceptance(o.id,rc.id);
  IF(acceptance211->>'return_id',acceptance211->>'order_id',acceptance211->>'receipt_sequence') IS DISTINCT FROM(rc.id::text,o.id::text,rc.receipt_sequence::text) THEN
   RAISE EXCEPTION '211 full original native acceptance sequence differs' USING ERRCODE='23514';END IF;
  protocols:=protocols||jsonb_build_array(jsonb_build_object('return_id',rc.id,'receipt_id',acceptance211->'id','protocol',acceptance211->'protocol'));
  financial:=acceptance211->'financial';
  IF financial->>'financial_hash' IS DISTINCT FROM public.return_credit206_hash(financial-'financial_hash') THEN
   RAISE EXCEPTION '211 original acceptance financial hash differs' USING ERRCODE='23514';END IF;
  acceptances:=acceptances||jsonb_build_array(financial);
 END LOOP;
 FOR cr IN SELECT * FROM(
  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,'legacy' family FROM public.local_consumer_credit_receipts r JOIN public.local_consumer_credit_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)
  UNION ALL
  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,'destinations' family FROM public.return_credit206_receipts r JOIN public.return_credit206_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)
 )all_credits ORDER BY receipt_sequence,id LOOP
  IF cr.previous_receipt_id IS DISTINCT FROM prev OR cr.data IS DISTINCT FROM(cr.snapshot||jsonb_build_object('number',cr.number,'year',cr.year,'sequence',cr.sequence,'preview_id',cr.preview_id,'scope_hash',cr.scope_hash)) OR cr.number IS DISTINCT FROM cr.doc_number OR cr.scope_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot) OR cr.calculation_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot->'calculation') THEN RAISE EXCEPTION 'Niepełny previous credit207' USING ERRCODE='23514';END IF;
  previousj:=previousj||jsonb_build_array(jsonb_build_object('document_id',cr.document_id,'receipt_id',cr.id,'return_id',cr.return_id,'return_receipt_id',cr.return_receipt_id,'receipt_sequence',cr.receipt_sequence,'calculation',cr.snapshot->'calculation','calculation_hash',cr.calculation_hash));families:=families||jsonb_build_array(jsonb_build_object('document_id',cr.document_id,'receipt_id',cr.id,'family',cr.family,'created_at',to_char(cr.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));prev:=cr.id;
 END LOOP;
 resultj:=jsonb_build_object('schema','consumer-return-credit-source/v2','rejected_inspections',rejectedj,'physical_protocols',protocols,'credit_families',families,'original',jsonb_build_object('document',jsonb_build_object('id',d.id,'order_id',d.order_id,'number',d.number,'kind',d.kind,'mode',d.mode,'data',d.data,'created_at',to_char(d.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')),'receipt',jsonb_build_object('id',ir.id,'document_id',ir.document_id,'preview_id',ir.preview_id,'number',ir.number,'scope_hash',ir.scope_hash,'snapshot',ir.snapshot)),'acceptances',acceptances,'previous_credits',previousj,'selected_return_id',selected_return);
 IF octet_length(resultj::text)>33554432 THEN RAISE EXCEPTION 'Całe źródło207 przekracza32MiB' USING ERRCODE='54000';END IF;RETURN resultj;
END$$;
REVOKE ALL ON FUNCTION public.return_credit211_source(uuid,uuid) FROM PUBLIC,dyna_app;

-- Install-only seed, before parent triggers and old206 FK replacement. Only
-- immutable EXISTING206 credits may create rows in this phase. No arbitrary
-- tenant/acceptance input, no169/PZ/stock/counter creation or old-row changes.
DO $seed211$
DECLARE old_tenant text:=current_setting('app.tenant_id',true);credit_row public.return_credit206_receipts;
 admission_row public.return_credit206_admissions;frame211 jsonb;decision211 jsonb;acceptance211 jsonb;
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('session_replication_role')<>'origin'
 OR EXISTS(SELECT FROM public.return_credit211_acceptances)
 OR EXISTS(SELECT FROM pg_trigger WHERE tgrelid='public.return_credit211_acceptances'::regclass AND NOT tgisinternal) THEN
  RAISE EXCEPTION '211 exact fresh install-only historical206 seed phase required' USING ERRCODE='55000';END IF;
 FOR credit_row IN SELECT * FROM public.return_credit206_receipts ORDER BY tenant_id,original_document_id,receipt_sequence,id LOOP
  PERFORM set_config('app.tenant_id',credit_row.tenant_id::text,true);
  SELECT * INTO admission_row FROM public.return_credit206_admissions WHERE(tenant_id,id)=(credit_row.tenant_id,credit_row.id);
  IF admission_row.id IS NULL OR(credit_row.document_id,credit_row.preview_id,credit_row.actor_id,credit_row.api_key_id,credit_row.root_xid,credit_row.transaction_started_at,credit_row.backend_pid)
   IS DISTINCT FROM(admission_row.document_id,admission_row.preview_id,admission_row.actor_id,admission_row.api_key_id,admission_row.root_xid,admission_row.transaction_started_at,admission_row.backend_pid) THEN
   RAISE EXCEPTION '211 historical206 admission differs' USING ERRCODE='23514';END IF;
  frame211:=public.return_credit211_source(credit_row.original_document_id,credit_row.return_id);
  decision211:=public.return_credit206_calculate(frame211);
  IF decision211->>'status' IS DISTINCT FROM 'already_credited' THEN RAISE EXCEPTION '211 historical206 whole credit chain differs' USING ERRCODE='23514';END IF;
  acceptance211:=public.return_credit211_acceptance(credit_row.order_id,credit_row.return_id);
  IF acceptance211->>'family' IS DISTINCT FROM 'catalog169'
   OR(credit_row.return_receipt_id,credit_row.receipt_sequence) IS DISTINCT FROM((acceptance211->>'id')::uuid,(acceptance211->>'receipt_sequence')::integer)
   OR credit_row.snapshot#>>'{calculation,financial_hash}' IS DISTINCT FROM acceptance211#>>'{financial,financial_hash}' THEN
   RAISE EXCEPTION '211 historical206 concrete169 receipt differs' USING ERRCODE='23514';END IF;
  IF(SELECT count(*) FROM public.return_credit211_acceptances WHERE tenant_id=credit_row.tenant_id)>=2000
   OR(SELECT coalesce(sum(pg_column_size(v)),0) FROM public.return_credit211_acceptances v WHERE v.tenant_id=credit_row.tenant_id)+octet_length(acceptance211::text)>33554432 THEN
   RAISE EXCEPTION '211 complete historical seed exceeds existing parent budget' USING ERRCODE='54000';END IF;
  INSERT INTO public.return_credit211_acceptances(tenant_id,id,order_id,return_id,family,catalog_receipt_id,destination_receipt_id,receipt_sequence,financial,evidence_hash,credit_admission_id)
  VALUES(credit_row.tenant_id,(acceptance211->>'id')::uuid,credit_row.order_id,credit_row.return_id,'catalog169',(acceptance211->>'id')::uuid,NULL,
   (acceptance211->>'receipt_sequence')::integer,acceptance211->'financial',acceptance211->>'evidence_hash',credit_row.id);
 END LOOP;
 PERFORM set_config('app.tenant_id',coalesce(old_tenant,''),true);
 IF(SELECT count(*) FROM public.return_credit211_acceptances)<>(SELECT count(*) FROM public.return_credit206_receipts) THEN
  RAISE EXCEPTION '211 complete historical seed cardinality differs' USING ERRCODE='23514';END IF;
END $seed211$;

CREATE FUNCTION public.return_credit211_parent_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $parent211$
DECLARE ca public.return_credit206_admissions;p public.return_credit206_previews;f jsonb;expected_catalog uuid;expected_destination uuid;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION '211 acceptance parent is immutable' USING ERRCODE='23514';END IF;
 IF current_user<>'postgres' OR session_user<>'postgres' OR NEW.tenant_id IS DISTINCT FROM nullif(current_setting('app.tenant_id',true),'')::uuid
 OR current_setting('session_replication_role')<>'origin' THEN RAISE EXCEPTION '211 private issue parent context required' USING ERRCODE='42501';END IF;
 SELECT * INTO ca FROM public.return_credit206_admissions WHERE(tenant_id,id,root_xid,transaction_started_at,backend_pid)=
  (NEW.tenant_id,NEW.credit_admission_id,pg_current_xact_id(),transaction_timestamp(),pg_backend_pid());
 SELECT * INTO p FROM public.return_credit206_previews WHERE(tenant_id,id)=(NEW.tenant_id,ca.preview_id);
 IF ca.id IS NULL OR p.id IS NULL OR(p.actor_id,p.api_key_id) IS DISTINCT FROM(ca.actor_id,ca.api_key_id)
 OR(NEW.order_id,NEW.return_id,NEW.id,NEW.receipt_sequence) IS DISTINCT FROM(p.order_id,p.return_id,(p.snapshot#>>'{calculation,return_receipt_id}')::uuid,(p.snapshot#>>'{calculation,receipt_sequence}')::integer)
 OR NEW.created_at<transaction_timestamp() THEN RAISE EXCEPTION '211 parent requires current exact issue admission and preview' USING ERRCODE='23514';END IF;
 PERFORM public.return_credit206_require(ca.actor_id,ca.api_key_id,true,false);
 f:=public.return_credit211_acceptance(p.order_id,p.return_id);
 IF f->>'family'='catalog169' THEN expected_catalog:=(f->>'id')::uuid;ELSE expected_destination:=(f->>'id')::uuid;END IF;
 IF(NEW.family,NEW.id,NEW.catalog_receipt_id,NEW.destination_receipt_id,NEW.receipt_sequence,NEW.financial,NEW.evidence_hash)
  IS DISTINCT FROM(f->>'family',(f->>'id')::uuid,expected_catalog,expected_destination,(f->>'receipt_sequence')::integer,f->'financial',f->>'evidence_hash')
 OR p.snapshot#>>'{calculation,financial_hash}' IS DISTINCT FROM f#>>'{financial,financial_hash}' THEN
  RAISE EXCEPTION '211 complete current financial parent differs from original history' USING ERRCODE='23514';END IF;
 IF(SELECT count(*) FROM public.return_credit211_acceptances WHERE tenant_id=NEW.tenant_id)>=2000
 OR(SELECT coalesce(sum(pg_column_size(v)),0) FROM public.return_credit211_acceptances v WHERE v.tenant_id=NEW.tenant_id)+pg_column_size(NEW)>33554432 THEN
  RAISE EXCEPTION '211 complete parent history exceeds existing budget' USING ERRCODE='54000';END IF;
 RETURN NEW;
END $parent211$;
CREATE TRIGGER return_credit211_parent_guard BEFORE INSERT OR UPDATE OR DELETE ON public.return_credit211_acceptances
 FOR EACH ROW EXECUTE FUNCTION public.return_credit211_parent_guard();
CREATE FUNCTION public.return_credit211_no_truncate() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $truncate211$
BEGIN RAISE EXCEPTION '211 acceptance parents cannot be truncated' USING ERRCODE='23514';END $truncate211$;
CREATE TRIGGER return_credit211_no_truncate BEFORE TRUNCATE ON public.return_credit211_acceptances FOR EACH STATEMENT EXECUTE FUNCTION public.return_credit211_no_truncate();

-- The future issue port calls this AFTER its real206 issue admission is inserted,
-- BEFORE its credit receipt/FK. It is not called by GET/source/preview.
CREATE FUNCTION public.return_credit211_ensure_parent(credit_admission uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET TimeZone='UTC' AS $ensure211$
DECLARE tenant uuid:=nullif(current_setting('app.tenant_id',true),'')::uuid;ca public.return_credit206_admissions;
 p public.return_credit206_previews;f jsonb;saved public.return_credit211_acceptances;
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR tenant IS NULL OR current_setting('session_replication_role')<>'origin' THEN
  RAISE EXCEPTION '211 private current issue context required' USING ERRCODE='42501';END IF;
 SELECT * INTO ca FROM public.return_credit206_admissions WHERE(tenant_id,id,root_xid,transaction_started_at,backend_pid)=
  (tenant,credit_admission,pg_current_xact_id(),transaction_timestamp(),pg_backend_pid());
 SELECT * INTO p FROM public.return_credit206_previews WHERE(tenant_id,id)=(tenant,ca.preview_id);
 IF ca.id IS NULL OR p.id IS NULL OR(p.actor_id,p.api_key_id) IS DISTINCT FROM(ca.actor_id,ca.api_key_id) THEN
  RAISE EXCEPTION '211 parent creation has no exact current issue admission' USING ERRCODE='23514';END IF;
 PERFORM public.return_credit206_require(ca.actor_id,ca.api_key_id,true,false);
 f:=public.return_credit211_acceptance(p.order_id,p.return_id);
 IF(p.snapshot#>>'{calculation,return_receipt_id}',p.snapshot#>>'{calculation,receipt_sequence}',p.snapshot#>>'{calculation,financial_hash}')
  IS DISTINCT FROM(f->>'id',f->>'receipt_sequence',f#>>'{financial,financial_hash}') THEN
  RAISE EXCEPTION '211 original issue preview no longer matches its full acceptance' USING ERRCODE='23514';END IF;
 SELECT * INTO saved FROM public.return_credit211_acceptances WHERE(tenant_id,return_id)=(tenant,p.return_id) FOR UPDATE;
 IF saved.id IS NOT NULL THEN
  IF(saved.id,saved.order_id,saved.family,saved.receipt_sequence,saved.financial,saved.evidence_hash)
   IS DISTINCT FROM((f->>'id')::uuid,p.order_id,f->>'family',(f->>'receipt_sequence')::integer,f->'financial',f->>'evidence_hash') THEN
   RAISE EXCEPTION '211 existing immutable parent differs' USING ERRCODE='23514';END IF;
  RETURN saved.id;
 END IF;
 INSERT INTO public.return_credit211_acceptances(tenant_id,id,order_id,return_id,family,catalog_receipt_id,destination_receipt_id,
  receipt_sequence,financial,evidence_hash,credit_admission_id)
 VALUES(tenant,(f->>'id')::uuid,p.order_id,p.return_id,f->>'family',CASE WHEN f->>'family'='catalog169' THEN(f->>'id')::uuid END,
  CASE WHEN f->>'family'='destinations148' THEN(f->>'id')::uuid END,(f->>'receipt_sequence')::integer,f->'financial',f->>'evidence_hash',ca.id);
 RETURN(f->>'id')::uuid;
END $ensure211$;

CREATE FUNCTION public.return_credit211_parent_complete() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $complete211$
DECLARE a public.return_credit206_admissions;p public.return_credit206_previews;r public.return_credit206_receipts;
BEGIN
 SELECT * INTO a FROM public.return_credit206_admissions WHERE(tenant_id,id)=(NEW.tenant_id,NEW.credit_admission_id);
 SELECT * INTO p FROM public.return_credit206_previews WHERE(tenant_id,id)=(NEW.tenant_id,a.preview_id);
 SELECT * INTO r FROM public.return_credit206_receipts WHERE(tenant_id,id)=(NEW.tenant_id,a.id);
 IF a.id IS NULL OR p.id IS NULL OR r.id IS NULL OR(r.document_id,r.preview_id,r.order_id,r.return_id,r.return_receipt_id,r.receipt_sequence)
  IS DISTINCT FROM(a.document_id,p.id,NEW.order_id,NEW.return_id,NEW.id,NEW.receipt_sequence)
 OR(r.root_xid,r.transaction_started_at,r.backend_pid) IS DISTINCT FROM(a.root_xid,a.transaction_started_at,a.backend_pid) THEN
  RAISE EXCEPTION '211 parent cannot commit without its complete original credit issue' USING ERRCODE='23514';END IF;
 RETURN NULL;
END $complete211$;
CREATE CONSTRAINT TRIGGER return_credit211_parent_complete AFTER INSERT ON public.return_credit211_acceptances
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.return_credit211_parent_complete();
REVOKE ALL ON FUNCTION public.return_credit211_frozen_physical(uuid),public.return_credit211_history148(uuid),
 public.return_credit211_acceptance(uuid,uuid),public.return_credit211_parent_guard(),public.return_credit211_no_truncate(),
 public.return_credit211_ensure_parent(uuid),public.return_credit211_parent_complete() FROM PUBLIC,dyna_app;

-- Structural comparison only: the separate Native/cold contract must authorize
-- the complete literal SOURCE-compiled vector before inserting any seal row.
-- A stored compiler hash or current pg_catalog row is not independent provenance.
CREATE TABLE public.return_credit211_metadata(
 id boolean PRIMARY KEY CHECK(id),profile text NOT NULL CHECK(profile='209-to211-destinations148-credit/v1'),
 own_records jsonb NOT NULL,changes jsonb NOT NULL,removed jsonb NOT NULL,
 original206 jsonb NOT NULL,original208 jsonb NOT NULL,original209 jsonb NOT NULL,
 source_compiler_sha256 text NOT NULL CHECK(source_compiler_sha256~'^[a-f0-9]{64}$'),
 CHECK(jsonb_typeof(own_records)='array' AND jsonb_array_length(own_records)>0 AND octet_length(own_records::text)<=8388608),
 CHECK(jsonb_typeof(changes)='array' AND jsonb_array_length(changes)=6 AND octet_length(changes::text)<=8388608),
 CHECK(jsonb_typeof(removed)='array' AND jsonb_array_length(removed)=2 AND octet_length(removed::text)<=8388608)
);
ALTER TABLE public.return_credit211_metadata ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.return_credit211_metadata FORCE ROW LEVEL SECURITY;
CREATE POLICY owner_scope ON public.return_credit211_metadata TO CURRENT_USER USING(true) WITH CHECK(true);
REVOKE ALL ON public.return_credit211_metadata FROM PUBLIC,dyna_app;

CREATE FUNCTION public.return_credit211_metadata_valid() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $valid211$
DECLARE m public.return_credit211_metadata;observed jsonb;expected jsonb;
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('session_replication_role')<>'origin'
 OR(SELECT count(*) FROM public.return_credit211_metadata)<>1 THEN RETURN false;END IF;
 SELECT * INTO m FROM public.return_credit211_metadata WHERE id;
 IF m.profile IS DISTINCT FROM '209-to211-destinations148-credit/v1'
 OR m.changes IS DISTINCT FROM '[{"kind":"function","key":"public.return_credit206_source(did uuid, selected_return uuid)","before":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"acl_null":false,"argument_modes":null,"argument_names":["did","selected_return"],"arguments":"did uuid, selected_return uuid","binary":null,"config":["search_path=pg_catalog, public","TimeZone=UTC"],"cost":100,"defaults":null,"definition":"CREATE OR REPLACE FUNCTION public.return_credit206_source(did uuid, selected_return uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;d documents;ir local_invoice_receipts;o orders;rc record;rr catalog_stock_return_receipts; financial jsonb;inspection_row record;rejectedj jsonb:=''[]'';acceptances jsonb:=''[]'';previousj jsonb:=''[]'';protocols jsonb:=''[]'';families jsonb:=''[]'';cr record;prev uuid;seq integer:=0;resultj jsonb;BEGIN\n PERFORM public.local_invoice_locks();SELECT * INTO d FROM public.documents WHERE(tenant_id,id)=(t,did);\n IF d.id IS NULL OR d.kind<>''invoice'' OR d.mode<>''local_invoice'' THEN RAISE EXCEPTION ''Brak prawdziwej FV157'' USING ERRCODE=''P0002'';END IF;\n SELECT * INTO o FROM public.orders WHERE(tenant_id,id)=(t,d.order_id) FOR UPDATE;\n IF NOT EXISTS(SELECT FROM public.catalog_stock_return_receipts native_receipt JOIN public.catalog_stock_return_admissions aa ON(aa.tenant_id,aa.id)=(native_receipt.tenant_id,native_receipt.id) WHERE(native_receipt.tenant_id,native_receipt.order_id)=(t,o.id) AND aa.protocol=''destinations_v1'' AND aa.sealed) AND NOT EXISTS(SELECT FROM public.return_destination_admissions rejected_admission WHERE(rejected_admission.tenant_id,rejected_admission.order_id)=(t,o.id) AND rejected_admission.after_snapshot IS NOT NULL AND rejected_admission.payload->>''action''=''reject'' AND rejected_admission.payload#>>''{snapshot,protocol}''=''destinations_v1'') THEN RAISE EXCEPTION ''Destination successor requires actual received destinations history'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO ir FROM public.local_invoice_receipts WHERE(tenant_id,document_id)=(t,d.id);\n IF ir.id IS NULL OR(d.order_id,d.number) IS DISTINCT FROM(ir.order_id,ir.number)\n OR d.data IS DISTINCT FROM(ir.snapshot||jsonb_build_object(''number'',ir.number,''preview_id'',ir.preview_id,''scope_hash'',ir.scope_hash,''local_only'',true,''ksef_state'',''not_submitted'',''fiscalized'',false))\n OR ir.scope_hash IS DISTINCT FROM public.local_invoice_hash(ir.snapshot) OR ir.snapshot->>''currency''<>''PLN'' OR ir.snapshot#>>''{buyer,kind}''<>''consumer''\n OR ir.snapshot#>>''{buyer,address,country}''<>''PL'' OR ir.snapshot->>''tax_regime''<>''ordinary_domestic'' OR ir.snapshot->>''rounding_method''<>''gross_line_half_up''\n OR o.currency<>''PLN'' OR o.fulfillment_kind<>''sale'' THEN RAISE EXCEPTION ''Obcy original157 snapshot207'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT FROM documents x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'')) OR EXISTS(SELECT FROM invoice_plans x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'') AND x.state NOT IN(''preview'',''cancelled'')) THEN RAISE EXCEPTION ''Istniejąca inna korekta wymaga odrębnego uzgodnienia'' USING ERRCODE=''23514'';END IF;\n IF(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 OR (SELECT coalesce(sum(pg_column_size(payload_return.snapshot)),0) FROM public.catalog_stock_return_receipts payload_return WHERE(payload_return.tenant_id,payload_return.order_id)=(t,o.id))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.return_credit206_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.local_consumer_credit_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+pg_column_size(ir.snapshot)+(SELECT coalesce(sum(pg_column_size(da.payload)::numeric+pg_column_size(da.before_snapshot)+pg_column_size(da.after_snapshot)+pg_column_size(da.witnesses)+pg_column_size(ar.result)),0) FROM public.return_destination_admissions da JOIN public.return_assistant_receipts ar ON(ar.tenant_id,ar.id)=(da.tenant_id,da.receipt_id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action''=''reject'')>33554432 THEN RAISE EXCEPTION ''Limit pełnej historii207'' USING ERRCODE=''54000'';END IF;\n FOR inspection_row IN SELECT ar.id FROM public.return_assistant_receipts ar JOIN public.return_destination_admissions da ON(da.tenant_id,da.receipt_id)=(ar.tenant_id,ar.id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action''=''reject'' AND da.payload#>>''{snapshot,protocol}''=''destinations_v1'' ORDER BY ar.created_at,ar.id LOOP\n  IF jsonb_array_length(rejectedj)>=1000 THEN RAISE EXCEPTION ''Complete rejected inspection budget'' USING ERRCODE=''54000'';END IF;\n  rejectedj:=rejectedj||jsonb_build_array(public.return_credit206_rejected_history(inspection_row.id));\n END LOOP;\n IF jsonb_array_length(rejectedj)+(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 THEN RAISE EXCEPTION ''Complete physical audit budget'' USING ERRCODE=''54000'';END IF;\n FOR rc IN SELECT * FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL ORDER BY receipt_sequence,id FOR SHARE LOOP\n  seq:=seq+1;\n  IF rc.legacy OR rc.remedy<>''refund'' OR rc.state NOT IN(''refund_pending'',''closed'') OR rc.receipt_sequence<>seq THEN RAISE EXCEPTION ''Nieobsługiwany lub niepełny ciąg RMA207'' USING ERRCODE=''23514'';END IF;\n  SELECT * INTO rr FROM public.catalog_stock_return_receipts WHERE(tenant_id,return_id,order_id)=(t,rc.id,o.id);\n  IF rr.id IS NULL THEN RAISE EXCEPTION ''Brak actual physical169 receipt207'' USING ERRCODE=''23514'';END IF;\n  PERFORM public.return_credit206_physical_history(rr.id);\n  protocols:=protocols||jsonb_build_array(jsonb_build_object(''return_id'',rc.id,''receipt_id'',rr.id,''protocol'',(SELECT protocol FROM public.catalog_stock_return_admissions WHERE(tenant_id,id)=(t,rr.id))));\n  financial:=jsonb_build_object(''return_id'',rc.id,''receipt_id'',rr.id,''receipt_sequence'',rc.receipt_sequence,\n   ''received_at'',to_char((rr.snapshot#>>''{return_case,received_at}'')::timestamptz AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"''),\n   ''refund_amount_minor'',rr.snapshot#>>''{return_case,refund_amount}'',''refunded_shipping_minor'',rr.snapshot#>>''{return_case,refunded_shipping}'',\n   ''items'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''item_id'',x->''item_id'',''accepted'',(x->>''accepted'')::bigint::text,''restocked'',(x->>''restocked'')::bigint::text,''refund_amount_minor'',(x->>''refund_amount'')::bigint::text) ORDER BY x->>''item_id''),''[]'') FROM jsonb_array_elements(rr.snapshot->''items'')x));\n  acceptances:=acceptances||jsonb_build_array(financial||jsonb_build_object(''financial_hash'',public.return_credit206_hash(financial)));\n END LOOP;\n FOR cr IN SELECT * FROM(\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''legacy'' family FROM public.local_consumer_credit_receipts r JOIN public.local_consumer_credit_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n  UNION ALL\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''destinations'' family FROM public.return_credit206_receipts r JOIN public.return_credit206_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n )all_credits ORDER BY receipt_sequence,id LOOP\n  IF cr.previous_receipt_id IS DISTINCT FROM prev OR cr.data IS DISTINCT FROM(cr.snapshot||jsonb_build_object(''number'',cr.number,''year'',cr.year,''sequence'',cr.sequence,''preview_id'',cr.preview_id,''scope_hash'',cr.scope_hash)) OR cr.number IS DISTINCT FROM cr.doc_number OR cr.scope_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot) OR cr.calculation_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot->''calculation'') THEN RAISE EXCEPTION ''Niepełny previous credit207'' USING ERRCODE=''23514'';END IF;\n  previousj:=previousj||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''return_id'',cr.return_id,''return_receipt_id'',cr.return_receipt_id,''receipt_sequence'',cr.receipt_sequence,''calculation'',cr.snapshot->''calculation'',''calculation_hash'',cr.calculation_hash));families:=families||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''family'',cr.family,''created_at'',to_char(cr.created_at AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')));prev:=cr.id;\n END LOOP;\n resultj:=jsonb_build_object(''schema'',''consumer-return-credit-source/v2'',''rejected_inspections'',rejectedj,''physical_protocols'',protocols,''credit_families'',families,''original'',jsonb_build_object(''document'',jsonb_build_object(''id'',d.id,''order_id'',d.order_id,''number'',d.number,''kind'',d.kind,''mode'',d.mode,''data'',d.data,''created_at'',to_char(d.created_at AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')),''receipt'',jsonb_build_object(''id'',ir.id,''document_id'',ir.document_id,''preview_id'',ir.preview_id,''number'',ir.number,''scope_hash'',ir.scope_hash,''snapshot'',ir.snapshot)),''acceptances'',acceptances,''previous_credits'',previousj,''selected_return_id'',selected_return);\n IF octet_length(resultj::text)>33554432 THEN RAISE EXCEPTION ''Całe źródło207 przekracza32MiB'' USING ERRCODE=''54000'';END IF;RETURN resultj;\nEND$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","result":"jsonb","returns_set":false,"rows":0,"security_definer":true,"source":"\nDECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;d documents;ir local_invoice_receipts;o orders;rc record;rr catalog_stock_return_receipts; financial jsonb;inspection_row record;rejectedj jsonb:=''[]'';acceptances jsonb:=''[]'';previousj jsonb:=''[]'';protocols jsonb:=''[]'';families jsonb:=''[]'';cr record;prev uuid;seq integer:=0;resultj jsonb;BEGIN\n PERFORM public.local_invoice_locks();SELECT * INTO d FROM public.documents WHERE(tenant_id,id)=(t,did);\n IF d.id IS NULL OR d.kind<>''invoice'' OR d.mode<>''local_invoice'' THEN RAISE EXCEPTION ''Brak prawdziwej FV157'' USING ERRCODE=''P0002'';END IF;\n SELECT * INTO o FROM public.orders WHERE(tenant_id,id)=(t,d.order_id) FOR UPDATE;\n IF NOT EXISTS(SELECT FROM public.catalog_stock_return_receipts native_receipt JOIN public.catalog_stock_return_admissions aa ON(aa.tenant_id,aa.id)=(native_receipt.tenant_id,native_receipt.id) WHERE(native_receipt.tenant_id,native_receipt.order_id)=(t,o.id) AND aa.protocol=''destinations_v1'' AND aa.sealed) AND NOT EXISTS(SELECT FROM public.return_destination_admissions rejected_admission WHERE(rejected_admission.tenant_id,rejected_admission.order_id)=(t,o.id) AND rejected_admission.after_snapshot IS NOT NULL AND rejected_admission.payload->>''action''=''reject'' AND rejected_admission.payload#>>''{snapshot,protocol}''=''destinations_v1'') THEN RAISE EXCEPTION ''Destination successor requires actual received destinations history'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO ir FROM public.local_invoice_receipts WHERE(tenant_id,document_id)=(t,d.id);\n IF ir.id IS NULL OR(d.order_id,d.number) IS DISTINCT FROM(ir.order_id,ir.number)\n OR d.data IS DISTINCT FROM(ir.snapshot||jsonb_build_object(''number'',ir.number,''preview_id'',ir.preview_id,''scope_hash'',ir.scope_hash,''local_only'',true,''ksef_state'',''not_submitted'',''fiscalized'',false))\n OR ir.scope_hash IS DISTINCT FROM public.local_invoice_hash(ir.snapshot) OR ir.snapshot->>''currency''<>''PLN'' OR ir.snapshot#>>''{buyer,kind}''<>''consumer''\n OR ir.snapshot#>>''{buyer,address,country}''<>''PL'' OR ir.snapshot->>''tax_regime''<>''ordinary_domestic'' OR ir.snapshot->>''rounding_method''<>''gross_line_half_up''\n OR o.currency<>''PLN'' OR o.fulfillment_kind<>''sale'' THEN RAISE EXCEPTION ''Obcy original157 snapshot207'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT FROM documents x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'')) OR EXISTS(SELECT FROM invoice_plans x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'') AND x.state NOT IN(''preview'',''cancelled'')) THEN RAISE EXCEPTION ''Istniejąca inna korekta wymaga odrębnego uzgodnienia'' USING ERRCODE=''23514'';END IF;\n IF(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 OR (SELECT coalesce(sum(pg_column_size(payload_return.snapshot)),0) FROM public.catalog_stock_return_receipts payload_return WHERE(payload_return.tenant_id,payload_return.order_id)=(t,o.id))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.return_credit206_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.local_consumer_credit_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+pg_column_size(ir.snapshot)+(SELECT coalesce(sum(pg_column_size(da.payload)::numeric+pg_column_size(da.before_snapshot)+pg_column_size(da.after_snapshot)+pg_column_size(da.witnesses)+pg_column_size(ar.result)),0) FROM public.return_destination_admissions da JOIN public.return_assistant_receipts ar ON(ar.tenant_id,ar.id)=(da.tenant_id,da.receipt_id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action''=''reject'')>33554432 THEN RAISE EXCEPTION ''Limit pełnej historii207'' USING ERRCODE=''54000'';END IF;\n FOR inspection_row IN SELECT ar.id FROM public.return_assistant_receipts ar JOIN public.return_destination_admissions da ON(da.tenant_id,da.receipt_id)=(ar.tenant_id,ar.id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action''=''reject'' AND da.payload#>>''{snapshot,protocol}''=''destinations_v1'' ORDER BY ar.created_at,ar.id LOOP\n  IF jsonb_array_length(rejectedj)>=1000 THEN RAISE EXCEPTION ''Complete rejected inspection budget'' USING ERRCODE=''54000'';END IF;\n  rejectedj:=rejectedj||jsonb_build_array(public.return_credit206_rejected_history(inspection_row.id));\n END LOOP;\n IF jsonb_array_length(rejectedj)+(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 THEN RAISE EXCEPTION ''Complete physical audit budget'' USING ERRCODE=''54000'';END IF;\n FOR rc IN SELECT * FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL ORDER BY receipt_sequence,id FOR SHARE LOOP\n  seq:=seq+1;\n  IF rc.legacy OR rc.remedy<>''refund'' OR rc.state NOT IN(''refund_pending'',''closed'') OR rc.receipt_sequence<>seq THEN RAISE EXCEPTION ''Nieobsługiwany lub niepełny ciąg RMA207'' USING ERRCODE=''23514'';END IF;\n  SELECT * INTO rr FROM public.catalog_stock_return_receipts WHERE(tenant_id,return_id,order_id)=(t,rc.id,o.id);\n  IF rr.id IS NULL THEN RAISE EXCEPTION ''Brak actual physical169 receipt207'' USING ERRCODE=''23514'';END IF;\n  PERFORM public.return_credit206_physical_history(rr.id);\n  protocols:=protocols||jsonb_build_array(jsonb_build_object(''return_id'',rc.id,''receipt_id'',rr.id,''protocol'',(SELECT protocol FROM public.catalog_stock_return_admissions WHERE(tenant_id,id)=(t,rr.id))));\n  financial:=jsonb_build_object(''return_id'',rc.id,''receipt_id'',rr.id,''receipt_sequence'',rc.receipt_sequence,\n   ''received_at'',to_char((rr.snapshot#>>''{return_case,received_at}'')::timestamptz AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"''),\n   ''refund_amount_minor'',rr.snapshot#>>''{return_case,refund_amount}'',''refunded_shipping_minor'',rr.snapshot#>>''{return_case,refunded_shipping}'',\n   ''items'',(SELECT coalesce(jsonb_agg(jsonb_build_object(''item_id'',x->''item_id'',''accepted'',(x->>''accepted'')::bigint::text,''restocked'',(x->>''restocked'')::bigint::text,''refund_amount_minor'',(x->>''refund_amount'')::bigint::text) ORDER BY x->>''item_id''),''[]'') FROM jsonb_array_elements(rr.snapshot->''items'')x));\n  acceptances:=acceptances||jsonb_build_array(financial||jsonb_build_object(''financial_hash'',public.return_credit206_hash(financial)));\n END LOOP;\n FOR cr IN SELECT * FROM(\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''legacy'' family FROM public.local_consumer_credit_receipts r JOIN public.local_consumer_credit_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n  UNION ALL\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''destinations'' family FROM public.return_credit206_receipts r JOIN public.return_credit206_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n )all_credits ORDER BY receipt_sequence,id LOOP\n  IF cr.previous_receipt_id IS DISTINCT FROM prev OR cr.data IS DISTINCT FROM(cr.snapshot||jsonb_build_object(''number'',cr.number,''year'',cr.year,''sequence'',cr.sequence,''preview_id'',cr.preview_id,''scope_hash'',cr.scope_hash)) OR cr.number IS DISTINCT FROM cr.doc_number OR cr.scope_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot) OR cr.calculation_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot->''calculation'') THEN RAISE EXCEPTION ''Niepełny previous credit207'' USING ERRCODE=''23514'';END IF;\n  previousj:=previousj||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''return_id'',cr.return_id,''return_receipt_id'',cr.return_receipt_id,''receipt_sequence'',cr.receipt_sequence,''calculation'',cr.snapshot->''calculation'',''calculation_hash'',cr.calculation_hash));families:=families||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''family'',cr.family,''created_at'',to_char(cr.created_at AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')));prev:=cr.id;\n END LOOP;\n resultj:=jsonb_build_object(''schema'',''consumer-return-credit-source/v2'',''rejected_inspections'',rejectedj,''physical_protocols'',protocols,''credit_families'',families,''original'',jsonb_build_object(''document'',jsonb_build_object(''id'',d.id,''order_id'',d.order_id,''number'',d.number,''kind'',d.kind,''mode'',d.mode,''data'',d.data,''created_at'',to_char(d.created_at AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')),''receipt'',jsonb_build_object(''id'',ir.id,''document_id'',ir.document_id,''preview_id'',ir.preview_id,''number'',ir.number,''scope_hash'',ir.scope_hash,''snapshot'',ir.snapshot)),''acceptances'',acceptances,''previous_credits'',previousj,''selected_return_id'',selected_return);\n IF octet_length(resultj::text)>33554432 THEN RAISE EXCEPTION ''Całe źródło207 przekracza32MiB'' USING ERRCODE=''54000'';END IF;RETURN resultj;\nEND","strict":false,"support":null,"variadic":null,"volatility":"v"},"after":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"acl_null":false,"argument_modes":null,"argument_names":["did","selected_return"],"arguments":"did uuid, selected_return uuid","binary":null,"config":["search_path=pg_catalog, public","TimeZone=UTC"],"cost":100,"defaults":null,"definition":"CREATE OR REPLACE FUNCTION public.return_credit206_source(did uuid, selected_return uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;d documents;ir local_invoice_receipts;o orders;rc record;rr catalog_stock_return_receipts; financial jsonb;acceptance211 jsonb;inspection_row record;rejectedj jsonb:=''[]'';acceptances jsonb:=''[]'';previousj jsonb:=''[]'';protocols jsonb:=''[]'';families jsonb:=''[]'';cr record;prev uuid;seq integer:=0;resultj jsonb;BEGIN\n PERFORM public.local_invoice_locks();SELECT * INTO d FROM public.documents WHERE(tenant_id,id)=(t,did);\n IF d.id IS NULL OR d.kind<>''invoice'' OR d.mode<>''local_invoice'' THEN RAISE EXCEPTION ''Brak prawdziwej FV157'' USING ERRCODE=''P0002'';END IF;\n SELECT * INTO o FROM public.orders WHERE(tenant_id,id)=(t,d.order_id) FOR UPDATE;\n IF NOT EXISTS(SELECT FROM public.catalog_stock_return_receipts native_receipt JOIN public.catalog_stock_return_admissions aa ON(aa.tenant_id,aa.id)=(native_receipt.tenant_id,native_receipt.id) WHERE(native_receipt.tenant_id,native_receipt.order_id)=(t,o.id) AND aa.protocol=''destinations_v1'' AND aa.sealed) AND NOT EXISTS(SELECT FROM public.return_destination_admissions rejected_admission WHERE(rejected_admission.tenant_id,rejected_admission.order_id)=(t,o.id) AND rejected_admission.after_snapshot IS NOT NULL AND rejected_admission.payload->>''action'' IN(''receive'',''reject'') AND rejected_admission.payload#>>''{snapshot,protocol}''=''destinations_v1'') THEN RAISE EXCEPTION ''Destination successor requires actual received destinations history'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO ir FROM public.local_invoice_receipts WHERE(tenant_id,document_id)=(t,d.id);\n IF ir.id IS NULL OR(d.order_id,d.number) IS DISTINCT FROM(ir.order_id,ir.number)\n OR d.data IS DISTINCT FROM(ir.snapshot||jsonb_build_object(''number'',ir.number,''preview_id'',ir.preview_id,''scope_hash'',ir.scope_hash,''local_only'',true,''ksef_state'',''not_submitted'',''fiscalized'',false))\n OR ir.scope_hash IS DISTINCT FROM public.local_invoice_hash(ir.snapshot) OR ir.snapshot->>''currency''<>''PLN'' OR ir.snapshot#>>''{buyer,kind}''<>''consumer''\n OR ir.snapshot#>>''{buyer,address,country}''<>''PL'' OR ir.snapshot->>''tax_regime''<>''ordinary_domestic'' OR ir.snapshot->>''rounding_method''<>''gross_line_half_up''\n OR o.currency<>''PLN'' OR o.fulfillment_kind<>''sale'' THEN RAISE EXCEPTION ''Obcy original157 snapshot207'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT FROM documents x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'')) OR EXISTS(SELECT FROM invoice_plans x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'') AND x.state NOT IN(''preview'',''cancelled'')) THEN RAISE EXCEPTION ''Istniejąca inna korekta wymaga odrębnego uzgodnienia'' USING ERRCODE=''23514'';END IF;\n IF(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 OR (SELECT coalesce(sum(pg_column_size(payload_return.snapshot)),0) FROM public.catalog_stock_return_receipts payload_return WHERE(payload_return.tenant_id,payload_return.order_id)=(t,o.id))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.return_credit206_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.local_consumer_credit_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+pg_column_size(ir.snapshot)+(SELECT coalesce(sum(pg_column_size(da.payload)::numeric+pg_column_size(da.before_snapshot)+pg_column_size(da.after_snapshot)+pg_column_size(da.witnesses)+pg_column_size(ar.result)),0) FROM public.return_destination_admissions da JOIN public.return_assistant_receipts ar ON(ar.tenant_id,ar.id)=(da.tenant_id,da.receipt_id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action'' IN(''receive'',''reject''))+(SELECT coalesce(sum(pg_column_size(parent211)),0) FROM public.return_credit211_acceptances parent211 WHERE(parent211.tenant_id,parent211.order_id)=(t,o.id))>33554432 THEN RAISE EXCEPTION ''Limit pełnej historii207'' USING ERRCODE=''54000'';END IF;\n FOR inspection_row IN SELECT ar.id FROM public.return_assistant_receipts ar JOIN public.return_destination_admissions da ON(da.tenant_id,da.receipt_id)=(ar.tenant_id,ar.id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action''=''reject'' AND da.payload#>>''{snapshot,protocol}''=''destinations_v1'' ORDER BY ar.created_at,ar.id LOOP\n  IF jsonb_array_length(rejectedj)>=1000 THEN RAISE EXCEPTION ''Complete rejected inspection budget'' USING ERRCODE=''54000'';END IF;\n  rejectedj:=rejectedj||jsonb_build_array(public.return_credit206_rejected_history(inspection_row.id));\n END LOOP;\n IF jsonb_array_length(rejectedj)+(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 THEN RAISE EXCEPTION ''Complete physical audit budget'' USING ERRCODE=''54000'';END IF;\n FOR rc IN SELECT * FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL ORDER BY receipt_sequence,id FOR SHARE LOOP\n  seq:=seq+1;\n  IF rc.legacy OR rc.remedy<>''refund'' OR rc.state NOT IN(''refund_pending'',''closed'') OR rc.receipt_sequence<>seq THEN RAISE EXCEPTION ''Nieobsługiwany lub niepełny ciąg RMA207'' USING ERRCODE=''23514'';END IF;\n  acceptance211:=public.return_credit211_acceptance(o.id,rc.id);\n  IF(acceptance211->>''return_id'',acceptance211->>''order_id'',acceptance211->>''receipt_sequence'') IS DISTINCT FROM(rc.id::text,o.id::text,rc.receipt_sequence::text) THEN\n   RAISE EXCEPTION ''211 full original native acceptance sequence differs'' USING ERRCODE=''23514'';END IF;\n  protocols:=protocols||jsonb_build_array(jsonb_build_object(''return_id'',rc.id,''receipt_id'',acceptance211->''id'',''protocol'',acceptance211->''protocol''));\n  financial:=acceptance211->''financial'';\n  IF financial->>''financial_hash'' IS DISTINCT FROM public.return_credit206_hash(financial-''financial_hash'') THEN\n   RAISE EXCEPTION ''211 original acceptance financial hash differs'' USING ERRCODE=''23514'';END IF;\n  acceptances:=acceptances||jsonb_build_array(financial);\n END LOOP;\n FOR cr IN SELECT * FROM(\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''legacy'' family FROM public.local_consumer_credit_receipts r JOIN public.local_consumer_credit_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n  UNION ALL\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''destinations'' family FROM public.return_credit206_receipts r JOIN public.return_credit206_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n )all_credits ORDER BY receipt_sequence,id LOOP\n  IF cr.previous_receipt_id IS DISTINCT FROM prev OR cr.data IS DISTINCT FROM(cr.snapshot||jsonb_build_object(''number'',cr.number,''year'',cr.year,''sequence'',cr.sequence,''preview_id'',cr.preview_id,''scope_hash'',cr.scope_hash)) OR cr.number IS DISTINCT FROM cr.doc_number OR cr.scope_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot) OR cr.calculation_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot->''calculation'') THEN RAISE EXCEPTION ''Niepełny previous credit207'' USING ERRCODE=''23514'';END IF;\n  previousj:=previousj||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''return_id'',cr.return_id,''return_receipt_id'',cr.return_receipt_id,''receipt_sequence'',cr.receipt_sequence,''calculation'',cr.snapshot->''calculation'',''calculation_hash'',cr.calculation_hash));families:=families||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''family'',cr.family,''created_at'',to_char(cr.created_at AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')));prev:=cr.id;\n END LOOP;\n resultj:=jsonb_build_object(''schema'',''consumer-return-credit-source/v2'',''rejected_inspections'',rejectedj,''physical_protocols'',protocols,''credit_families'',families,''original'',jsonb_build_object(''document'',jsonb_build_object(''id'',d.id,''order_id'',d.order_id,''number'',d.number,''kind'',d.kind,''mode'',d.mode,''data'',d.data,''created_at'',to_char(d.created_at AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')),''receipt'',jsonb_build_object(''id'',ir.id,''document_id'',ir.document_id,''preview_id'',ir.preview_id,''number'',ir.number,''scope_hash'',ir.scope_hash,''snapshot'',ir.snapshot)),''acceptances'',acceptances,''previous_credits'',previousj,''selected_return_id'',selected_return);\n IF octet_length(resultj::text)>33554432 THEN RAISE EXCEPTION ''Całe źródło207 przekracza32MiB'' USING ERRCODE=''54000'';END IF;RETURN resultj;\nEND$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","result":"jsonb","returns_set":false,"rows":0,"security_definer":true,"source":"\nDECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;d documents;ir local_invoice_receipts;o orders;rc record;rr catalog_stock_return_receipts; financial jsonb;acceptance211 jsonb;inspection_row record;rejectedj jsonb:=''[]'';acceptances jsonb:=''[]'';previousj jsonb:=''[]'';protocols jsonb:=''[]'';families jsonb:=''[]'';cr record;prev uuid;seq integer:=0;resultj jsonb;BEGIN\n PERFORM public.local_invoice_locks();SELECT * INTO d FROM public.documents WHERE(tenant_id,id)=(t,did);\n IF d.id IS NULL OR d.kind<>''invoice'' OR d.mode<>''local_invoice'' THEN RAISE EXCEPTION ''Brak prawdziwej FV157'' USING ERRCODE=''P0002'';END IF;\n SELECT * INTO o FROM public.orders WHERE(tenant_id,id)=(t,d.order_id) FOR UPDATE;\n IF NOT EXISTS(SELECT FROM public.catalog_stock_return_receipts native_receipt JOIN public.catalog_stock_return_admissions aa ON(aa.tenant_id,aa.id)=(native_receipt.tenant_id,native_receipt.id) WHERE(native_receipt.tenant_id,native_receipt.order_id)=(t,o.id) AND aa.protocol=''destinations_v1'' AND aa.sealed) AND NOT EXISTS(SELECT FROM public.return_destination_admissions rejected_admission WHERE(rejected_admission.tenant_id,rejected_admission.order_id)=(t,o.id) AND rejected_admission.after_snapshot IS NOT NULL AND rejected_admission.payload->>''action'' IN(''receive'',''reject'') AND rejected_admission.payload#>>''{snapshot,protocol}''=''destinations_v1'') THEN RAISE EXCEPTION ''Destination successor requires actual received destinations history'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO ir FROM public.local_invoice_receipts WHERE(tenant_id,document_id)=(t,d.id);\n IF ir.id IS NULL OR(d.order_id,d.number) IS DISTINCT FROM(ir.order_id,ir.number)\n OR d.data IS DISTINCT FROM(ir.snapshot||jsonb_build_object(''number'',ir.number,''preview_id'',ir.preview_id,''scope_hash'',ir.scope_hash,''local_only'',true,''ksef_state'',''not_submitted'',''fiscalized'',false))\n OR ir.scope_hash IS DISTINCT FROM public.local_invoice_hash(ir.snapshot) OR ir.snapshot->>''currency''<>''PLN'' OR ir.snapshot#>>''{buyer,kind}''<>''consumer''\n OR ir.snapshot#>>''{buyer,address,country}''<>''PL'' OR ir.snapshot->>''tax_regime''<>''ordinary_domestic'' OR ir.snapshot->>''rounding_method''<>''gross_line_half_up''\n OR o.currency<>''PLN'' OR o.fulfillment_kind<>''sale'' THEN RAISE EXCEPTION ''Obcy original157 snapshot207'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT FROM documents x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'')) OR EXISTS(SELECT FROM invoice_plans x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'') AND x.state NOT IN(''preview'',''cancelled'')) THEN RAISE EXCEPTION ''Istniejąca inna korekta wymaga odrębnego uzgodnienia'' USING ERRCODE=''23514'';END IF;\n IF(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 OR (SELECT coalesce(sum(pg_column_size(payload_return.snapshot)),0) FROM public.catalog_stock_return_receipts payload_return WHERE(payload_return.tenant_id,payload_return.order_id)=(t,o.id))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.return_credit206_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.local_consumer_credit_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+pg_column_size(ir.snapshot)+(SELECT coalesce(sum(pg_column_size(da.payload)::numeric+pg_column_size(da.before_snapshot)+pg_column_size(da.after_snapshot)+pg_column_size(da.witnesses)+pg_column_size(ar.result)),0) FROM public.return_destination_admissions da JOIN public.return_assistant_receipts ar ON(ar.tenant_id,ar.id)=(da.tenant_id,da.receipt_id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action'' IN(''receive'',''reject''))+(SELECT coalesce(sum(pg_column_size(parent211)),0) FROM public.return_credit211_acceptances parent211 WHERE(parent211.tenant_id,parent211.order_id)=(t,o.id))>33554432 THEN RAISE EXCEPTION ''Limit pełnej historii207'' USING ERRCODE=''54000'';END IF;\n FOR inspection_row IN SELECT ar.id FROM public.return_assistant_receipts ar JOIN public.return_destination_admissions da ON(da.tenant_id,da.receipt_id)=(ar.tenant_id,ar.id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action''=''reject'' AND da.payload#>>''{snapshot,protocol}''=''destinations_v1'' ORDER BY ar.created_at,ar.id LOOP\n  IF jsonb_array_length(rejectedj)>=1000 THEN RAISE EXCEPTION ''Complete rejected inspection budget'' USING ERRCODE=''54000'';END IF;\n  rejectedj:=rejectedj||jsonb_build_array(public.return_credit206_rejected_history(inspection_row.id));\n END LOOP;\n IF jsonb_array_length(rejectedj)+(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 THEN RAISE EXCEPTION ''Complete physical audit budget'' USING ERRCODE=''54000'';END IF;\n FOR rc IN SELECT * FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL ORDER BY receipt_sequence,id FOR SHARE LOOP\n  seq:=seq+1;\n  IF rc.legacy OR rc.remedy<>''refund'' OR rc.state NOT IN(''refund_pending'',''closed'') OR rc.receipt_sequence<>seq THEN RAISE EXCEPTION ''Nieobsługiwany lub niepełny ciąg RMA207'' USING ERRCODE=''23514'';END IF;\n  acceptance211:=public.return_credit211_acceptance(o.id,rc.id);\n  IF(acceptance211->>''return_id'',acceptance211->>''order_id'',acceptance211->>''receipt_sequence'') IS DISTINCT FROM(rc.id::text,o.id::text,rc.receipt_sequence::text) THEN\n   RAISE EXCEPTION ''211 full original native acceptance sequence differs'' USING ERRCODE=''23514'';END IF;\n  protocols:=protocols||jsonb_build_array(jsonb_build_object(''return_id'',rc.id,''receipt_id'',acceptance211->''id'',''protocol'',acceptance211->''protocol''));\n  financial:=acceptance211->''financial'';\n  IF financial->>''financial_hash'' IS DISTINCT FROM public.return_credit206_hash(financial-''financial_hash'') THEN\n   RAISE EXCEPTION ''211 original acceptance financial hash differs'' USING ERRCODE=''23514'';END IF;\n  acceptances:=acceptances||jsonb_build_array(financial);\n END LOOP;\n FOR cr IN SELECT * FROM(\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''legacy'' family FROM public.local_consumer_credit_receipts r JOIN public.local_consumer_credit_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n  UNION ALL\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''destinations'' family FROM public.return_credit206_receipts r JOIN public.return_credit206_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n )all_credits ORDER BY receipt_sequence,id LOOP\n  IF cr.previous_receipt_id IS DISTINCT FROM prev OR cr.data IS DISTINCT FROM(cr.snapshot||jsonb_build_object(''number'',cr.number,''year'',cr.year,''sequence'',cr.sequence,''preview_id'',cr.preview_id,''scope_hash'',cr.scope_hash)) OR cr.number IS DISTINCT FROM cr.doc_number OR cr.scope_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot) OR cr.calculation_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot->''calculation'') THEN RAISE EXCEPTION ''Niepełny previous credit207'' USING ERRCODE=''23514'';END IF;\n  previousj:=previousj||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''return_id'',cr.return_id,''return_receipt_id'',cr.return_receipt_id,''receipt_sequence'',cr.receipt_sequence,''calculation'',cr.snapshot->''calculation'',''calculation_hash'',cr.calculation_hash));families:=families||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''family'',cr.family,''created_at'',to_char(cr.created_at AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')));prev:=cr.id;\n END LOOP;\n resultj:=jsonb_build_object(''schema'',''consumer-return-credit-source/v2'',''rejected_inspections'',rejectedj,''physical_protocols'',protocols,''credit_families'',families,''original'',jsonb_build_object(''document'',jsonb_build_object(''id'',d.id,''order_id'',d.order_id,''number'',d.number,''kind'',d.kind,''mode'',d.mode,''data'',d.data,''created_at'',to_char(d.created_at AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')),''receipt'',jsonb_build_object(''id'',ir.id,''document_id'',ir.document_id,''preview_id'',ir.preview_id,''number'',ir.number,''scope_hash'',ir.scope_hash,''snapshot'',ir.snapshot)),''acceptances'',acceptances,''previous_credits'',previousj,''selected_return_id'',selected_return);\n IF octet_length(resultj::text)>33554432 THEN RAISE EXCEPTION ''Całe źródło207 przekracza32MiB'' USING ERRCODE=''54000'';END IF;RETURN resultj;\nEND","strict":false,"support":null,"variadic":null,"volatility":"v"}},{"kind":"function","key":"public.return_credit206_issue(pid uuid, b jsonb, uid uuid, kid uuid)","before":{"acl":[{"grantable":false,"grantee":"dyna_app","grantor":"postgres","privilege":"EXECUTE"},{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"acl_null":false,"argument_modes":null,"argument_names":["pid","b","uid","kid"],"arguments":"pid uuid, b jsonb, uid uuid, kid uuid","binary":null,"config":["search_path=pg_catalog, public","TimeZone=UTC"],"cost":100,"defaults":null,"definition":"CREATE OR REPLACE FUNCTION public.return_credit206_issue(pid uuid, b jsonb, uid uuid, kid uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$DECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;p return_credit206_previews;r return_credit206_receipts;f jsonb;h text;yr integer;seq integer;series uuid;seller text;v_prefix text;claimed record;prev uuid;eid uuid:=gen_random_uuid();did uuid:=gen_random_uuid();num text;BEGIN\n PERFORM public.return_credit206_require(uid,kid,true,false);PERFORM public.local_invoice_locks();h:=public.local_invoice_request_hash(''consumer-return-credit-issue'',pid,b,uid,kid);\n SELECT * INTO r FROM return_credit206_receipts WHERE(tenant_id,client_key)=(t,(b->>''client_key'')::uuid);\n IF r.id IS NOT NULL THEN IF(r.preview_id,r.actor_id,r.api_key_id,r.request_hash,r.request) IS DISTINCT FROM(pid,uid,kid,h,b) THEN RAISE EXCEPTION ''Klucz issue207 ma inny oryginał'' USING ERRCODE=''23514'';END IF;PERFORM public.return_credit206_require(uid,kid,true,true);RETURN to_jsonb(r)||jsonb_build_object(''reused'',true);END IF;\n SELECT * INTO p FROM return_credit206_previews WHERE(tenant_id,id)=(t,pid);\n IF p.id IS NULL THEN RAISE EXCEPTION ''Brak podglądu207'' USING ERRCODE=''P0002'';END IF;\n IF(p.actor_id,p.api_key_id) IS DISTINCT FROM(uid,kid) OR p.expires_at<=clock_timestamp() OR b IS DISTINCT FROM jsonb_build_object(''client_key'',b->>''client_key'',''scope_hash'',p.scope_hash,''confirmed'',true,''local_only'',true) THEN RAISE EXCEPTION ''Brak dokładnej bieżącej zgody207'' USING ERRCODE=''23514'';END IF;\n f:=public.return_credit206_frame(p.original_document_id,p.request);\n IF f IS DISTINCT FROM p.snapshot OR public.return_credit206_hash(f)<>p.scope_hash OR public.return_credit206_hash(f->''calculation'')<>p.calculation_hash THEN RAISE EXCEPTION ''Pełne źródło207 zmieniło się po preview'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT FROM return_credit206_receipts WHERE(tenant_id,return_id)=(t,p.return_id)) OR EXISTS(SELECT FROM public.local_consumer_credit_receipts WHERE(tenant_id,return_id)=(t,p.return_id)) THEN RAISE EXCEPTION ''RMA ma już oryginalną KOR207'' USING ERRCODE=''23514'';END IF;\n series:=(f#>>''{correction_series,id}'')::uuid;v_prefix:=f#>>''{correction_series,prefix}'';seller:=f#>>''{original_document,data,seller,tax_id}'';yr:=extract(year FROM(f->>''issue_date'')::date)::integer;\n PERFORM pg_advisory_xact_lock(hashtextextended(''consumer-credit-namespace:''||seller||'':''||v_prefix,0));\n SELECT * INTO claimed FROM return_credit206_namespaces WHERE seller_tax_id=seller AND return_credit206_namespaces.prefix=v_prefix;\n IF FOUND AND(claimed.tenant_id,claimed.series_id) IS DISTINCT FROM(t,series) THEN RAISE EXCEPTION ''Numeracja KOR207 jest już przypisana do innego źródła'' USING ERRCODE=''23514'';END IF;\n IF NOT FOUND THEN INSERT INTO return_credit206_namespaces VALUES(seller,v_prefix,t,series);END IF;\n SELECT last_number INTO seq FROM return_credit206_counters WHERE(tenant_id,series_id,year)=(t,series,yr) FOR UPDATE;seq:=coalesce(seq,0)+1;IF seq>999999 THEN RAISE EXCEPTION ''Limit rocznej numeracji207'' USING ERRCODE=''54000'';END IF;\n num:=v_prefix||''/''||yr::text||''/''||lpad(seq::text,6,''0'');SELECT id INTO prev FROM(SELECT id,receipt_sequence FROM public.return_credit206_receipts WHERE(tenant_id,original_document_id)=(t,p.original_document_id) UNION ALL SELECT id,receipt_sequence FROM public.local_consumer_credit_receipts WHERE(tenant_id,original_document_id)=(t,p.original_document_id))credits ORDER BY receipt_sequence DESC LIMIT 1;\n INSERT INTO return_credit206_admissions VALUES(eid,t,did,p.id,uid,kid,(b->>''client_key'')::uuid,h,num,yr,seq,pg_current_xact_id(),transaction_timestamp(),pg_backend_pid());\n INSERT INTO return_credit206_documents VALUES(did,t,p.original_document_id,p.order_id,p.return_id,''correction'',''consumer_return_credit'',num,f||jsonb_build_object(''number'',num,''year'',yr,''sequence'',seq,''preview_id'',p.id,''scope_hash'',p.scope_hash),clock_timestamp());\n INSERT INTO return_credit206_receipts(id,tenant_id,document_id,preview_id,original_document_id,original_receipt_id,order_id,return_id,return_receipt_id,receipt_sequence,previous_receipt_id,actor_id,api_key_id,client_key,request,request_hash,scope_hash,calculation_hash,snapshot,series_id,year,sequence,number,root_xid,transaction_started_at,backend_pid)\n VALUES(eid,t,did,p.id,p.original_document_id,p.original_receipt_id,p.order_id,p.return_id,(f#>>''{calculation,return_receipt_id}'')::uuid,(f#>>''{calculation,receipt_sequence}'')::integer,prev,uid,kid,(b->>''client_key'')::uuid,b,h,p.scope_hash,p.calculation_hash,f,series,yr,seq,num,pg_current_xact_id(),transaction_timestamp(),pg_backend_pid()) RETURNING * INTO r;\n IF seq=1 THEN INSERT INTO return_credit206_counters VALUES(t,series,yr,seq);ELSE UPDATE return_credit206_counters SET last_number=seq WHERE(tenant_id,series_id,year)=(t,series,yr);END IF;\n PERFORM public.return_credit206_require(uid,kid,true,true);RETURN to_jsonb(r)||jsonb_build_object(''reused'',false);\nEND$function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","result":"jsonb","returns_set":false,"rows":0,"security_definer":true,"source":"DECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;p return_credit206_previews;r return_credit206_receipts;f jsonb;h text;yr integer;seq integer;series uuid;seller text;v_prefix text;claimed record;prev uuid;eid uuid:=gen_random_uuid();did uuid:=gen_random_uuid();num text;BEGIN\n PERFORM public.return_credit206_require(uid,kid,true,false);PERFORM public.local_invoice_locks();h:=public.local_invoice_request_hash(''consumer-return-credit-issue'',pid,b,uid,kid);\n SELECT * INTO r FROM return_credit206_receipts WHERE(tenant_id,client_key)=(t,(b->>''client_key'')::uuid);\n IF r.id IS NOT NULL THEN IF(r.preview_id,r.actor_id,r.api_key_id,r.request_hash,r.request) IS DISTINCT FROM(pid,uid,kid,h,b) THEN RAISE EXCEPTION ''Klucz issue207 ma inny oryginał'' USING ERRCODE=''23514'';END IF;PERFORM public.return_credit206_require(uid,kid,true,true);RETURN to_jsonb(r)||jsonb_build_object(''reused'',true);END IF;\n SELECT * INTO p FROM return_credit206_previews WHERE(tenant_id,id)=(t,pid);\n IF p.id IS NULL THEN RAISE EXCEPTION ''Brak podglądu207'' USING ERRCODE=''P0002'';END IF;\n IF(p.actor_id,p.api_key_id) IS DISTINCT FROM(uid,kid) OR p.expires_at<=clock_timestamp() OR b IS DISTINCT FROM jsonb_build_object(''client_key'',b->>''client_key'',''scope_hash'',p.scope_hash,''confirmed'',true,''local_only'',true) THEN RAISE EXCEPTION ''Brak dokładnej bieżącej zgody207'' USING ERRCODE=''23514'';END IF;\n f:=public.return_credit206_frame(p.original_document_id,p.request);\n IF f IS DISTINCT FROM p.snapshot OR public.return_credit206_hash(f)<>p.scope_hash OR public.return_credit206_hash(f->''calculation'')<>p.calculation_hash THEN RAISE EXCEPTION ''Pełne źródło207 zmieniło się po preview'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT FROM return_credit206_receipts WHERE(tenant_id,return_id)=(t,p.return_id)) OR EXISTS(SELECT FROM public.local_consumer_credit_receipts WHERE(tenant_id,return_id)=(t,p.return_id)) THEN RAISE EXCEPTION ''RMA ma już oryginalną KOR207'' USING ERRCODE=''23514'';END IF;\n series:=(f#>>''{correction_series,id}'')::uuid;v_prefix:=f#>>''{correction_series,prefix}'';seller:=f#>>''{original_document,data,seller,tax_id}'';yr:=extract(year FROM(f->>''issue_date'')::date)::integer;\n PERFORM pg_advisory_xact_lock(hashtextextended(''consumer-credit-namespace:''||seller||'':''||v_prefix,0));\n SELECT * INTO claimed FROM return_credit206_namespaces WHERE seller_tax_id=seller AND return_credit206_namespaces.prefix=v_prefix;\n IF FOUND AND(claimed.tenant_id,claimed.series_id) IS DISTINCT FROM(t,series) THEN RAISE EXCEPTION ''Numeracja KOR207 jest już przypisana do innego źródła'' USING ERRCODE=''23514'';END IF;\n IF NOT FOUND THEN INSERT INTO return_credit206_namespaces VALUES(seller,v_prefix,t,series);END IF;\n SELECT last_number INTO seq FROM return_credit206_counters WHERE(tenant_id,series_id,year)=(t,series,yr) FOR UPDATE;seq:=coalesce(seq,0)+1;IF seq>999999 THEN RAISE EXCEPTION ''Limit rocznej numeracji207'' USING ERRCODE=''54000'';END IF;\n num:=v_prefix||''/''||yr::text||''/''||lpad(seq::text,6,''0'');SELECT id INTO prev FROM(SELECT id,receipt_sequence FROM public.return_credit206_receipts WHERE(tenant_id,original_document_id)=(t,p.original_document_id) UNION ALL SELECT id,receipt_sequence FROM public.local_consumer_credit_receipts WHERE(tenant_id,original_document_id)=(t,p.original_document_id))credits ORDER BY receipt_sequence DESC LIMIT 1;\n INSERT INTO return_credit206_admissions VALUES(eid,t,did,p.id,uid,kid,(b->>''client_key'')::uuid,h,num,yr,seq,pg_current_xact_id(),transaction_timestamp(),pg_backend_pid());\n INSERT INTO return_credit206_documents VALUES(did,t,p.original_document_id,p.order_id,p.return_id,''correction'',''consumer_return_credit'',num,f||jsonb_build_object(''number'',num,''year'',yr,''sequence'',seq,''preview_id'',p.id,''scope_hash'',p.scope_hash),clock_timestamp());\n INSERT INTO return_credit206_receipts(id,tenant_id,document_id,preview_id,original_document_id,original_receipt_id,order_id,return_id,return_receipt_id,receipt_sequence,previous_receipt_id,actor_id,api_key_id,client_key,request,request_hash,scope_hash,calculation_hash,snapshot,series_id,year,sequence,number,root_xid,transaction_started_at,backend_pid)\n VALUES(eid,t,did,p.id,p.original_document_id,p.original_receipt_id,p.order_id,p.return_id,(f#>>''{calculation,return_receipt_id}'')::uuid,(f#>>''{calculation,receipt_sequence}'')::integer,prev,uid,kid,(b->>''client_key'')::uuid,b,h,p.scope_hash,p.calculation_hash,f,series,yr,seq,num,pg_current_xact_id(),transaction_timestamp(),pg_backend_pid()) RETURNING * INTO r;\n IF seq=1 THEN INSERT INTO return_credit206_counters VALUES(t,series,yr,seq);ELSE UPDATE return_credit206_counters SET last_number=seq WHERE(tenant_id,series_id,year)=(t,series,yr);END IF;\n PERFORM public.return_credit206_require(uid,kid,true,true);RETURN to_jsonb(r)||jsonb_build_object(''reused'',false);\nEND","strict":false,"support":null,"variadic":null,"volatility":"v"},"after":{"acl":[{"grantable":false,"grantee":"dyna_app","granto