edit211_parent_complete()","kind":"function","value":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"acl_null":false,"argument_modes":null,"argument_names":null,"arguments":"","binary":null,"config":["search_path=pg_catalog, public"],"cost":100,"defaults":null,"definition":"CREATE OR REPLACE FUNCTION public.return_credit211_parent_complete()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE a public.return_credit206_admissions;p public.return_credit206_previews;r public.return_credit206_receipts;\nBEGIN\n SELECT * INTO a FROM public.return_credit206_admissions WHERE(tenant_id,id)=(NEW.tenant_id,NEW.credit_admission_id);\n SELECT * INTO p FROM public.return_credit206_previews WHERE(tenant_id,id)=(NEW.tenant_id,a.preview_id);\n SELECT * INTO r FROM public.return_credit206_receipts WHERE(tenant_id,id)=(NEW.tenant_id,a.id);\n IF a.id IS NULL OR p.id IS NULL OR r.id IS NULL OR(r.document_id,r.preview_id,r.order_id,r.return_id,r.return_receipt_id,r.receipt_sequence)\n  IS DISTINCT FROM(a.document_id,p.id,NEW.order_id,NEW.return_id,NEW.id,NEW.receipt_sequence)\n OR(r.root_xid,r.transaction_started_at,r.backend_pid) IS DISTINCT FROM(a.root_xid,a.transaction_started_at,a.backend_pid) THEN\n  RAISE EXCEPTION ''211 parent cannot commit without its complete original credit issue'' USING ERRCODE=''23514'';END IF;\n RETURN NULL;\nEND $function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","result":"trigger","returns_set":false,"rows":0,"security_definer":true,"source":"\nDECLARE a public.return_credit206_admissions;p public.return_credit206_previews;r public.return_credit206_receipts;\nBEGIN\n SELECT * INTO a FROM public.return_credit206_admissions WHERE(tenant_id,id)=(NEW.tenant_id,NEW.credit_admission_id);\n SELECT * INTO p FROM public.return_credit206_previews WHERE(tenant_id,id)=(NEW.tenant_id,a.preview_id);\n SELECT * INTO r FROM public.return_credit206_receipts WHERE(tenant_id,id)=(NEW.tenant_id,a.id);\n IF a.id IS NULL OR p.id IS NULL OR r.id IS NULL OR(r.document_id,r.preview_id,r.order_id,r.return_id,r.return_receipt_id,r.receipt_sequence)\n  IS DISTINCT FROM(a.document_id,p.id,NEW.order_id,NEW.return_id,NEW.id,NEW.receipt_sequence)\n OR(r.root_xid,r.transaction_started_at,r.backend_pid) IS DISTINCT FROM(a.root_xid,a.transaction_started_at,a.backend_pid) THEN\n  RAISE EXCEPTION ''211 parent cannot commit without its complete original credit issue'' USING ERRCODE=''23514'';END IF;\n RETURN NULL;\nEND ","strict":false,"support":null,"variadic":null,"volatility":"v"}},{"key":"public.return_credit211_parent_guard()","kind":"function","value":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"acl_null":false,"argument_modes":null,"argument_names":null,"arguments":"","binary":null,"config":["search_path=pg_catalog, public","TimeZone=UTC"],"cost":100,"defaults":null,"definition":"CREATE OR REPLACE FUNCTION public.return_credit211_parent_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE ca public.return_credit206_admissions;p public.return_credit206_previews;f jsonb;expected_catalog uuid;expected_destination uuid;\nBEGIN\n IF TG_OP<>''INSERT'' THEN RAISE EXCEPTION ''211 acceptance parent is immutable'' USING ERRCODE=''23514'';END IF;\n IF current_user<>''postgres'' OR session_user<>''postgres'' OR NEW.tenant_id IS DISTINCT FROM nullif(current_setting(''app.tenant_id'',true),'''')::uuid\n OR current_setting(''session_replication_role'')<>''origin'' THEN RAISE EXCEPTION ''211 private issue parent context required'' USING ERRCODE=''42501'';END IF;\n SELECT * INTO ca FROM public.return_credit206_admissions WHERE(tenant_id,id,root_xid,transaction_started_at,backend_pid)=\n  (NEW.tenant_id,NEW.credit_admission_id,pg_current_xact_id(),transaction_timestamp(),pg_backend_pid());\n SELECT * INTO p FROM public.return_credit206_previews WHERE(tenant_id,id)=(NEW.tenant_id,ca.preview_id);\n IF ca.id IS NULL OR p.id IS NULL OR(p.actor_id,p.api_key_id) IS DISTINCT FROM(ca.actor_id,ca.api_key_id)\n OR(NEW.order_id,NEW.return_id,NEW.id,NEW.receipt_sequence) IS DISTINCT FROM(p.order_id,p.return_id,(p.snapshot#>>''{calculation,return_receipt_id}'')::uuid,(p.snapshot#>>''{calculation,receipt_sequence}'')::integer)\n OR NEW.created_at<transaction_timestamp() THEN RAISE EXCEPTION ''211 parent requires current exact issue admission and preview'' USING ERRCODE=''23514'';END IF;\n PERFORM public.return_credit206_require(ca.actor_id,ca.api_key_id,true,false);\n f:=public.return_credit211_acceptance(p.order_id,p.return_id);\n IF f->>''family''=''catalog169'' THEN expected_catalog:=(f->>''id'')::uuid;ELSE expected_destination:=(f->>''id'')::uuid;END IF;\n IF(NEW.family,NEW.id,NEW.catalog_receipt_id,NEW.destination_receipt_id,NEW.receipt_sequence,NEW.financial,NEW.evidence_hash)\n  IS DISTINCT FROM(f->>''family'',(f->>''id'')::uuid,expected_catalog,expected_destination,(f->>''receipt_sequence'')::integer,f->''financial'',f->>''evidence_hash'')\n OR p.snapshot#>>''{calculation,financial_hash}'' IS DISTINCT FROM f#>>''{financial,financial_hash}'' THEN\n  RAISE EXCEPTION ''211 complete current financial parent differs from original history'' USING ERRCODE=''23514'';END IF;\n IF(SELECT count(*) FROM public.return_credit211_acceptances WHERE tenant_id=NEW.tenant_id)>=2000\n OR(SELECT coalesce(sum(pg_column_size(v)),0) FROM public.return_credit211_acceptances v WHERE v.tenant_id=NEW.tenant_id)+pg_column_size(NEW)>33554432 THEN\n  RAISE EXCEPTION ''211 complete parent history exceeds existing budget'' USING ERRCODE=''54000'';END IF;\n RETURN NEW;\nEND $function$\n","kind":"f","language":"plpgsql","leakproof":false,"owner":"postgres","parallel":"u","result":"trigger","returns_set":false,"rows":0,"security_definer":true,"source":"\nDECLARE ca public.return_credit206_admissions;p public.return_credit206_previews;f jsonb;expected_catalog uuid;expected_destination uuid;\nBEGIN\n IF TG_OP<>''INSERT'' THEN RAISE EXCEPTION ''211 acceptance parent is immutable'' USING ERRCODE=''23514'';END IF;\n IF current_user<>''postgres'' OR session_user<>''postgres'' OR NEW.tenant_id IS DISTINCT FROM nullif(current_setting(''app.tenant_id'',true),'''')::uuid\n OR current_setting(''session_replication_role'')<>''origin'' THEN RAISE EXCEPTION ''211 private issue parent context required'' USING ERRCODE=''42501'';END IF;\n SELECT * INTO ca FROM public.return_credit206_admissions WHERE(tenant_id,id,root_xid,transaction_started_at,backend_pid)=\n  (NEW.tenant_id,NEW.credit_admission_id,pg_current_xact_id(),transaction_timestamp(),pg_backend_pid());\n SELECT * INTO p FROM public.return_credit206_previews WHERE(tenant_id,id)=(NEW.tenant_id,ca.preview_id);\n IF ca.id IS NULL OR p.id IS NULL OR(p.actor_id,p.api_key_id) IS DISTINCT FROM(ca.actor_id,ca.api_key_id)\n OR(NEW.order_id,NEW.return_id,NEW.id,NEW.receipt_sequence) IS DISTINCT FROM(p.order_id,p.return_id,(p.snapshot#>>''{calculation,return_receipt_id}'')::uuid,(p.snapshot#>>''{calculation,receipt_sequence}'')::integer)\n OR NEW.created_at<transaction_timestamp() THEN RAISE EXCEPTION ''211 parent requires current exact issue admission and preview'' USING ERRCODE=''23514'';END IF;\n PERFORM public.return_credit206_require(ca.actor_id,ca.api_key_id,true,false);\n f:=public.return_credit211_acceptance(p.order_id,p.return_id);\n IF f->>''family''=''catalog169'' THEN expected_catalog:=(f->>''id'')::uuid;ELSE expected_destination:=(f->>''id'')::uuid;END IF;\n IF(NEW.family,NEW.id,NEW.catalog_receipt_id,NEW.destination_receipt_id,NEW.receipt_sequence,NEW.financial,NEW.evidence_hash)\n  IS DISTINCT FROM(f->>''family'',(f->>''id'')::uuid,expected_catalog,expected_destination,(f->>''receipt_sequence'')::integer,f->''financial'',f->>''evidence_hash'')\n OR p.snapshot#>>''{calculation,financial_hash}'' IS DISTINCT FROM f#>>''{financial,financial_hash}'' THEN\n  RAISE EXCEPTION ''211 complete current financial parent differs from original history'' USING ERRCODE=''23514'';END IF;\n IF(SELECT count(*) FROM public.return_credit211_acceptances WHERE tenant_id=NEW.tenant_id)>=2000\n OR(SELECT coalesce(sum(pg_column_size(v)),0) FROM public.return_credit211_acceptances v WHERE v.tenant_id=NEW.tenant_id)+pg_column_size(NEW)>33554432 THEN\n  RAISE EXCEPTION ''211 complete parent history exceeds existing budget'' USING ERRCODE=''54000'';END IF;\n RETURN NEW;\nEND ","strict":false,"support":null,"variadic":null,"volatility":"v"}},{"key":"public.return_credit211_source(did uuid, selected_return uuid)","kind":"function","value":{"acl":[{"grantable":false,"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE"}],"acl_null":false,"argument_modes":null,"argument_names":["did","selected_return"],"arguments":"did uuid, selected_return uuid","binary":null,"config":["search_path=pg_catalog, public","TimeZone=UTC"],"cost":100,"defaults":null,"definition":"CREATE OR REPLACE FUNCTION public.return_credit211_source(did uuid, selected_return uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\n SET \"TimeZone\" TO ''UTC''\nAS $function$\nDECLARE t uuid:=nullif(current_setting(''app.tenant_id'',true),'''')::uuid;d documents;ir local_invoice_receipts;o orders;rc record;rr catalog_stock_return_receipts; financial jsonb;acceptance211 jsonb;inspection_row record;rejectedj jsonb:=''[]'';acceptances jsonb:=''[]'';previousj jsonb:=''[]'';protocols jsonb:=''[]'';families jsonb:=''[]'';cr record;prev uuid;seq integer:=0;resultj jsonb;BEGIN\n PERFORM public.local_invoice_locks();SELECT * INTO d FROM public.documents WHERE(tenant_id,id)=(t,did);\n IF d.id IS NULL OR d.kind<>''invoice'' OR d.mode<>''local_invoice'' THEN RAISE EXCEPTION ''Brak prawdziwej FV157'' USING ERRCODE=''P0002'';END IF;\n SELECT * INTO o FROM public.orders WHERE(tenant_id,id)=(t,d.order_id) FOR UPDATE;\n IF NOT EXISTS(SELECT FROM public.catalog_stock_return_receipts native_receipt JOIN public.catalog_stock_return_admissions aa ON(aa.tenant_id,aa.id)=(native_receipt.tenant_id,native_receipt.id) WHERE(native_receipt.tenant_id,native_receipt.order_id)=(t,o.id) AND aa.protocol=''destinations_v1'' AND aa.sealed) AND NOT EXISTS(SELECT FROM public.return_destination_admissions rejected_admission WHERE(rejected_admission.tenant_id,rejected_admission.order_id)=(t,o.id) AND rejected_admission.after_snapshot IS NOT NULL AND rejected_admission.payload->>''action'' IN(''receive'',''reject'') AND rejected_admission.payload#>>''{snapshot,protocol}''=''destinations_v1'') THEN RAISE EXCEPTION ''Destination successor requires actual received destinations history'' USING ERRCODE=''23514'';END IF;\n SELECT * INTO ir FROM public.local_invoice_receipts WHERE(tenant_id,document_id)=(t,d.id);\n IF ir.id IS NULL OR(d.order_id,d.number) IS DISTINCT FROM(ir.order_id,ir.number)\n OR d.data IS DISTINCT FROM(ir.snapshot||jsonb_build_object(''number'',ir.number,''preview_id'',ir.preview_id,''scope_hash'',ir.scope_hash,''local_only'',true,''ksef_state'',''not_submitted'',''fiscalized'',false))\n OR ir.scope_hash IS DISTINCT FROM public.local_invoice_hash(ir.snapshot) OR ir.snapshot->>''currency''<>''PLN'' OR ir.snapshot#>>''{buyer,kind}''<>''consumer''\n OR ir.snapshot#>>''{buyer,address,country}''<>''PL'' OR ir.snapshot->>''tax_regime''<>''ordinary_domestic'' OR ir.snapshot->>''rounding_method''<>''gross_line_half_up''\n OR o.currency<>''PLN'' OR o.fulfillment_kind<>''sale'' THEN RAISE EXCEPTION ''Obcy original157 snapshot207'' USING ERRCODE=''23514'';END IF;\n IF EXISTS(SELECT FROM documents x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'')) OR EXISTS(SELECT FROM invoice_plans x WHERE(x.tenant_id,x.order_id,x.kind)=(t,o.id,''correction'') AND x.state NOT IN(''preview'',''cancelled'')) THEN RAISE EXCEPTION ''Istniejąca inna korekta wymaga odrębnego uzgodnienia'' USING ERRCODE=''23514'';END IF;\n IF(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 OR (SELECT coalesce(sum(pg_column_size(payload_return.snapshot)),0) FROM public.catalog_stock_return_receipts payload_return WHERE(payload_return.tenant_id,payload_return.order_id)=(t,o.id))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.return_credit206_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+(SELECT coalesce(sum(pg_column_size(payload_credit.snapshot)),0) FROM public.local_consumer_credit_receipts payload_credit WHERE(payload_credit.tenant_id,payload_credit.original_document_id)=(t,did))+pg_column_size(ir.snapshot)+(SELECT coalesce(sum(pg_column_size(da.payload)::numeric+pg_column_size(da.before_snapshot)+pg_column_size(da.after_snapshot)+pg_column_size(da.witnesses)+pg_column_size(ar.result)),0) FROM public.return_destination_admissions da JOIN public.return_assistant_receipts ar ON(ar.tenant_id,ar.id)=(da.tenant_id,da.receipt_id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action'' IN(''receive'',''reject''))+(SELECT coalesce(sum(pg_column_size(parent211)),0) FROM public.return_credit211_acceptances parent211 WHERE(parent211.tenant_id,parent211.order_id)=(t,o.id))>33554432 THEN RAISE EXCEPTION ''Limit pełnej historii207'' USING ERRCODE=''54000'';END IF;\n FOR inspection_row IN SELECT ar.id FROM public.return_assistant_receipts ar JOIN public.return_destination_admissions da ON(da.tenant_id,da.receipt_id)=(ar.tenant_id,ar.id) WHERE(da.tenant_id,da.order_id)=(t,o.id) AND da.payload->>''action''=''reject'' AND da.payload#>>''{snapshot,protocol}''=''destinations_v1'' ORDER BY ar.created_at,ar.id LOOP\n  IF jsonb_array_length(rejectedj)>=1000 THEN RAISE EXCEPTION ''Complete rejected inspection budget'' USING ERRCODE=''54000'';END IF;\n  rejectedj:=rejectedj||jsonb_build_array(public.return_credit206_rejected_history(inspection_row.id));\n END LOOP;\n IF jsonb_array_length(rejectedj)+(SELECT count(*) FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL)>1000 THEN RAISE EXCEPTION ''Complete physical audit budget'' USING ERRCODE=''54000'';END IF;\n FOR rc IN SELECT * FROM public.return_cases WHERE(tenant_id,order_id)=(t,o.id) AND received_at IS NOT NULL ORDER BY receipt_sequence,id FOR SHARE LOOP\n  seq:=seq+1;\n  IF rc.legacy OR rc.remedy<>''refund'' OR rc.state NOT IN(''refund_pending'',''closed'') OR rc.receipt_sequence<>seq THEN RAISE EXCEPTION ''Nieobsługiwany lub niepełny ciąg RMA207'' USING ERRCODE=''23514'';END IF;\n  acceptance211:=public.return_credit211_acceptance(o.id,rc.id);\n  IF(acceptance211->>''return_id'',acceptance211->>''order_id'',acceptance211->>''receipt_sequence'') IS DISTINCT FROM(rc.id::text,o.id::text,rc.receipt_sequence::text) THEN\n   RAISE EXCEPTION ''211 full original native acceptance sequence differs'' USING ERRCODE=''23514'';END IF;\n  protocols:=protocols||jsonb_build_array(jsonb_build_object(''return_id'',rc.id,''receipt_id'',acceptance211->''id'',''protocol'',acceptance211->''protocol''));\n  financial:=acceptance211->''financial'';\n  IF financial->>''financial_hash'' IS DISTINCT FROM public.return_credit206_hash(financial-''financial_hash'') THEN\n   RAISE EXCEPTION ''211 original acceptance financial hash differs'' USING ERRCODE=''23514'';END IF;\n  acceptances:=acceptances||jsonb_build_array(financial);\n END LOOP;\n FOR cr IN SELECT * FROM(\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''legacy'' family FROM public.local_consumer_credit_receipts r JOIN public.local_consumer_credit_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n  UNION ALL\n  SELECT r.id,r.document_id,r.return_id,r.return_receipt_id,r.receipt_sequence,r.previous_receipt_id,r.snapshot,r.number,r.year,r.sequence,r.preview_id,r.scope_hash,r.calculation_hash,r.created_at,dc.data,dc.number doc_number,''destinations'' family FROM public.return_credit206_receipts r JOIN public.return_credit206_documents dc ON(dc.tenant_id,dc.id)=(r.tenant_id,r.document_id) WHERE(r.tenant_id,r.original_document_id)=(t,did)\n )all_credits ORDER BY receipt_sequence,id LOOP\n  IF cr.previous_receipt_id IS DISTINCT FROM prev OR cr.data IS DISTINCT FROM(cr.snapshot||jsonb_build_object(''number'',cr.number,''year'',cr.year,''sequence'',cr.sequence,''preview_id'',cr.preview_id,''scope_hash'',cr.scope_hash)) OR cr.number IS DISTINCT FROM cr.doc_number OR cr.scope_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot) OR cr.calculation_hash IS DISTINCT FROM public.return_credit206_hash(cr.snapshot->''calculation'') THEN RAISE EXCEPTION ''Niepełny previous credit207'' USING ERRCODE=''23514'';END IF;\n  previousj:=previousj||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''return_id'',cr.return_id,''return_receipt_id'',cr.return_receipt_id,''receipt_sequence'',cr.receipt_sequence,''calculation'',cr.snapshot->''calculation'',''calculation_hash'',cr.calculation_hash));families:=families||jsonb_build_array(jsonb_build_object(''document_id'',cr.document_id,''receipt_id'',cr.id,''family'',cr.family,''created_at'',to_char(cr.created_at AT TIME ZONE ''UTC'',''YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'')));prev:=cr.id;\n END LOOP;\n resultj:=jsonb_build_object(''schema'',''consumer-return-credit-source/v2'',''rejected_inspections'',rejectedj,''physical_protocols'',protocols,''credit_families'',families,''original'',jsonb_build_object(''document'',jsonb_build_object(''id'',d.id,''order_id'',d.order_id,''number'',d.number,''kind'',d.kind,''mode'',d.mode,''data'',d.data,''created_at'',to_char(d.created_at